insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('reichslaunzn', 'Reichslaunzn', '', '', '', '', 'Reichslanze', '[{"kategorie": "hist.", "text": "\"bedeutendes Relikt und Herrschaftsinsigne des [[Heiligen]] Römischen Reiches (auch als \"Lanze des Heiligen Mauritius\" oder [[Heilige Lanze]] bekannt)\""}, {"kategorie": "", "text": "Sie ist in der [[Wiener]] Schatzkammer ausgestellt und galt als ein Symbol der göttlichen Legitimation und des Schutzes für den römisch-deutschen Kaiser. Die Lanze war Teil der [[Reichsinsignien]], die bei der Krönung und anderen wichtigen Zeremonien eingesetzt wurden"}, {"kategorie": "", "text": "Die Heilige Lanze gilt als eines der wichtigsten Herrschaftszeichen und war für die [[Kaiser]] des Heiligen Römischen Reiches von besonderer religiöser Bedeutung. Ihr wurde nachgesagt, sie sei eine der Lanzoiden der biblischen Geschichte: Die Lanze, mit der der römische Soldat Longinus die Seite Jesu durchbohrt habe. Sie symbolisierte die göttliche Macht und den Schutz des Kaisers und stand für die Verpflichtung des Herrschers, das Christentum und das Reich zu verteidigen"}, {"kategorie": "", "text": "Die Heilige Lanze besteht aus einem langen Eisenschaft, in den ein Nagel eingefügt ist, der angeblich als Reliquie der Kreuzigung Jesu verehrt wurde. Die Lanze wurde im Laufe der Jahrhunderte mehrmals verstärkt und mit einem goldenen Silberband versehen, auf dem der Name und die Titel mehrerer Kaiser eingraviert sind. Diese Bandagierungen und Inschriften zeugen von der Wertschätzung der Lanze als wichtiges Reliquiar und Symbol"}, {"kategorie": "", "text": "Die genaue Herkunft der Heiligen Lanze ist unklar, jedoch wurde sie spätestens seit der Zeit [[Ottos]] I. (10. Jahrhundert) als kaiserliche Insigne verwendet und in Krönungszeremonien als Zeichen der göttlichen Legitimation des Herrschers eingesetzt. Sie war über Jahrhunderte in der Obhut der römisch-deutschen Kaiser und spielte eine wichtige Rolle in Zeremonien und Feldzügen, da sie als Schutzzeichen und göttliche Macht für den Kaiser angesehen wurde"}, {"kategorie": "", "text": "Nach der Auflösung des [[Heiligen]] Römischen Reiches im Jahr 1806 verblieb die Heilige Lanze, zusammen mit anderen [[Reichsinsignien]], in Wien und ist seither Teil der Sammlung in der [[Wiener]] Schatzkammer."}]'::jsonb, ''),
  ('kroenungsmauntl', 'Krönungsmauntl', '', '', '', '', 'Krönungsmantel', '[{"kategorie": "hist.", "text": "\"prachtvolles Kleidungsstück, das traditionell bei der Krönung eines [[Königs]] oder [[Kaisers]] getragen wurde\""}, {"kategorie": "", "text": "Der Krönungsmantel ist ein wichtiges Symbol der königlichen oder kaiserlichen Macht und Autorität und ist besonders aufwendig gestaltet, um die Erhabenheit und Würde des Herrschers zu unterstreichen"}, {"kategorie": "", "text": "Im [[Heiligen]] Römischen Reich war der Krönungsmantel ein zentrales Herrschaftsinsigne und symbolisierte die göttliche Auserwähltheit sowie den besonderen Status des Herrschers. Die aufwendige Gestaltung mit kostbaren Stoffen und Verzierungen sollte die Macht und den Reichtum des Herrschers sichtbar machen und war oft Ausdruck des Anspruchs auf göttliche Legitimation"}, {"kategorie": "", "text": "Der bekannteste Krönungsmantel ist der Mantel des [[Heiligen]] Römischen Reiches, der um das Jahr 1133 für den Kaiser des Reiches geschaffen wurde und bis zur Auflösung des Reiches 1806 verwendet wurde"}, {"kategorie": "", "text": "Der Mantel besteht aus purpurfarbenem Seidenstoff und ist mit goldgestickten Verzierungen versehen. Besonders auffällig ist das prachtvolle Adlerdesign, das für die Kaiserwürde steht, und die Darstellungen von Tieren und Pflanzenmotiven, die spirituelle und weltliche Symbole vereinen"}, {"kategorie": "", "text": "Nach dem Ende des Heiligen Römischen Reiches verblieb der Krönungsmantel mit anderen [[Reichsinsignien]] in Wien und wird seitdem in der [[Wiener]] Schatzkammer in der [[Hofburg]] verwahrt. Er gilt als einer der kostbarsten und am besten erhaltenen Krönungsmäntel des Mittelalters."}]'::jsonb, ''),
  ('pobstkrone', 'Pobstkrone', '', '', '', '', 'Papstkrone', '[{"kategorie": "rel.", "text": "charakteristisches und historisches Insigne des Papsttums (auch bekannt als [[Tiara]] oder [[Triregnum]])"}, {"kategorie": "", "text": "Die Papstkrone ist eine dreistufige Krone, die aus drei goldenen, aufeinander liegenden Ringen oder Kronen besteht, die durch ein nach oben zulaufendes Kegelgebilde verbunden sind. An der Spitze befindet sich häufig ein kleines Kreuz"}, {"kategorie": "", "text": "Die drei Kronen symbolisieren die dreifache Autorität des Papstes: als Oberster Priester (geistliche Macht), Oberster Richter (rechtliche Macht) und König der Welt (weltliche Macht über die Kirche)"}, {"kategorie": "", "text": "Die Papstkrone symbolisiert die übergeordnete Stellung des Papstes und seine geistliche Souveränität. Sie repräsentiert die Idee, dass der Papst nicht nur eine geistliche Autorität, sondern auch eine weltliche Führungskraft ist, die als „Vikar Christi“ auf Erden handelt. Der dreistufige Aufbau betont die umfassende Macht und Verantwortung des Papstes, die sich über spirituelle, juristische und zeitliche Bereiche erstrecken"}, {"kategorie": "", "text": "Die Papstkrone wurde über viele Jahrhunderte hinweg bei Krönungszeremonien neuer Päpste getragen. Papst Bonifatius VIII. führte das [[Triregnum]] (dreifache Krone) im 14. Jahrhundert ein"}, {"kategorie": "", "text": "Mit dem Zweiten Vatikanischen Konzil und dem veränderten Selbstverständnis der Kirche trug Papst Paul VI. letztmals 1963 die [[Tiara]] und legte sie symbolisch ab, um die spirituelle Autorität über die weltliche Machtstellung zu betonen"}, {"kategorie": "", "text": "Obwohl die Papstkrone heute nicht mehr getragen wird, bleibt sie ein wichtiges Symbol des Papsttums. Sie ist in Darstellungen des Papstwappens enthalten und verkörpert weiterhin die traditionelle, dreifache Autorität des Papstamtes"}, {"kategorie": "", "text": "Verschiedene historische [[Tiaren]], darunter prunkvolle Stücke, sind in Museen und der Vatikanischen Schatzkammer ausgestellt und erinnern an die Geschichte und den Anspruch des Papsttums."}]'::jsonb, ''),
  ('triregnum', 'Triregnum', '', '', '', '', 'Triregnum', '[{"kategorie": "rel.", "text": "charakteristisches und historisches Insigne des Papsttums (auch bekannt als [[Papstkrone]] oder [[Tiara]])"}, {"kategorie": "", "text": "Die Tiara ist eine dreistufige Krone, die aus drei goldenen, aufeinander liegenden Ringen oder Kronen besteht, die durch ein nach oben zulaufendes Kegelgebilde verbunden sind. An der Spitze befindet sich häufig ein kleines Kreuz"}, {"kategorie": "", "text": "Die drei Kronen symbolisieren die dreifache Autorität des Papstes: als Oberster Priester (geistliche Macht), Oberster Richter (rechtliche Macht) und König der Welt (weltliche Macht über die Kirche)"}, {"kategorie": "", "text": "Die Tiara symbolisiert die übergeordnete Stellung des Papstes und seine geistliche Souveränität. Sie repräsentiert die Idee, dass der Papst nicht nur eine geistliche Autorität, sondern auch eine weltliche Führungskraft ist, die als „Vikar Christi“ auf Erden handelt. Der dreistufige Aufbau betont die umfassende Macht und Verantwortung des Papstes, die sich über spirituelle, juristische und zeitliche Bereiche erstrecken"}, {"kategorie": "", "text": "Die Tiara wurde über viele Jahrhunderte hinweg bei Krönungszeremonien neuer Päpste getragen. Papst Bonifatius VIII. führte das [[Triregnum]] (dreifache Krone) im 14. Jahrhundert ein"}, {"kategorie": "", "text": "Mit dem Zweiten Vatikanischen Konzil und dem veränderten Selbstverständnis der Kirche trug Papst Paul VI. letztmals 1963 die Tiara und legte sie symbolisch ab, um die spirituelle Autorität über die weltliche Machtstellung zu betonen"}, {"kategorie": "", "text": "Obwohl die Tiara heute nicht mehr getragen wird, bleibt sie ein wichtiges Symbol des Papsttums. Sie ist in Darstellungen des Papstwappens enthalten und verkörpert weiterhin die traditionelle, dreifache Autorität des Papstamtes"}, {"kategorie": "", "text": "Verschiedene historische Tiaren, darunter prunkvolle Stücke, sind in Museen und der Vatikanischen Schatzkammer ausgestellt und erinnern an die Geschichte und den Anspruch des Papsttums."}]'::jsonb, ''),
  ('tiara', 'Tiara', '', '', '', '', 'Tiara', '[{"kategorie": "rel.", "text": "charakteristisches und historisches Insigne des Papsttums (auch bekannt als [[Papstkrone]] oder [[Triregnum]])"}, {"kategorie": "", "text": "Die Tiara ist eine dreistufige Krone, die aus drei goldenen, aufeinander liegenden Ringen oder Kronen besteht, die durch ein nach oben zulaufendes Kegelgebilde verbunden sind. An der Spitze befindet sich häufig ein kleines Kreuz"}, {"kategorie": "", "text": "Die drei Kronen symbolisieren die dreifache Autorität des Papstes: als Oberster Priester (geistliche Macht), Oberster Richter (rechtliche Macht) und König der Welt (weltliche Macht über die Kirche)"}, {"kategorie": "", "text": "Die Tiara symbolisiert die übergeordnete Stellung des Papstes und seine geistliche Souveränität. Sie repräsentiert die Idee, dass der Papst nicht nur eine geistliche Autorität, sondern auch eine weltliche Führungskraft ist, die als „Vikar Christi“ auf Erden handelt. Der dreistufige Aufbau betont die umfassende Macht und Verantwortung des Papstes, die sich über spirituelle, juristische und zeitliche Bereiche erstrecken"}, {"kategorie": "", "text": "Die Tiara wurde über viele Jahrhunderte hinweg bei Krönungszeremonien neuer Päpste getragen. Papst Bonifatius VIII. führte das [[Triregnum]] (dreifache Krone) im 14. Jahrhundert ein"}, {"kategorie": "", "text": "Mit dem Zweiten Vatikanischen Konzil und dem veränderten Selbstverständnis der Kirche trug Papst Paul VI. letztmals 1963 die Tiara und legte sie symbolisch ab, um die spirituelle Autorität über die weltliche Machtstellung zu betonen"}, {"kategorie": "", "text": "Obwohl die Tiara heute nicht mehr getragen wird, bleibt sie ein wichtiges Symbol des Papsttums. Sie ist in Darstellungen des Papstwappens enthalten und verkörpert weiterhin die traditionelle, dreifache Autorität des Papstamtes"}, {"kategorie": "", "text": "Verschiedene historische Tiaren, darunter prunkvolle Stücke, sind in Museen und der Vatikanischen Schatzkammer ausgestellt und erinnern an die Geschichte und den Anspruch des Papsttums."}]'::jsonb, ''),
  ('pallium', 'Pallium', '', '', '', '', 'Pallium', '[{"kategorie": "rel.", "text": "\"liturgisches Kleidungsstück in der katholischen Kirche, das als Zeichen der Würde und Autorität insbesondere dem Papst und Erzbischöfen verliehen wird\""}, {"kategorie": "", "text": "Das Pallium hat eine lange Tradition und symbolisiert die Verbundenheit mit dem Papst und die pastorale Verantwortung eines [[Erzbischofs]]"}, {"kategorie": "", "text": "Das Pallium ist eine schmale weiße Wollstola, die kreisförmig um die Schultern gelegt und vorne und hinten mit je einem kurzen Streifen herabhängt. Es ist mit sechs schwarzen Kreuzen bestickt, die an strategischen Stellen der Stola angebracht sind. Das Pallium wird traditionell mit Nadeln befestigt"}, {"kategorie": "", "text": "Das Pallium symbolisiert die pastorale Autorität und das Hirtenamt. Es steht für die Verbundenheit des Erzbischofs mit dem Papst und dessen Nachfolger Christi als „guter Hirte“, der seine Herde leitet und schützt. Als Zeichen der Einheit mit dem Papst drückt das Pallium die besondere Verantwortung und Verbindung eines [[Erzbischofs]] zu Rom aus"}, {"kategorie": "", "text": "Das Pallium wird traditionell vom Papst gesegnet und am Festtag der Heiligen Petrus und Paulus (29. Juni) neuen [[Metropoliten]] (Erzbischöfen) übergeben. Neben dem Papst selbst tragen nur Metropoliten das Pallium. Ein [[Metropolit]] ist der Erzbischof einer Kirchenprovinz und hat eine besondere Verantwortung über die [[Bistümer]] seiner Region"}, {"kategorie": "", "text": "Das Pallium hat seine Wurzeln in der antiken römischen Kleidung und wurde im Laufe der Jahrhunderte zu einem fest etablierten Insigne für die höheren Kirchenämter. Die Tradition, das Pallium dem Papst und Erzbischöfen zu verleihen, geht auf das frühe Mittelalter zurück und hat sich bis heute als Zeichen der Einheit und Verantwortung bewahrt."}]'::jsonb, ''),
  ('rudoifskrone', 'Rudoifskrone', '', '', '', '', 'Rudolfskrone', '[{"kategorie": "hist.", "text": "\"Krone, die ursprünglich für Kaiser [[Rudolf]] II. im Jahr 1602 angefertigt wurde und später zum Symbol des [[Kaisertums]] Österreich wurde\""}, {"kategorie": "", "text": "Sie ist ein herausragendes Stück der [[Habsburgischen]] Reichsinsignien und wurde von [[Franz]] I. (zuvor [[Franz II. des Heiligen Römischen Reiches]]) als offizielle [[Kaiserkrone]] des neu geschaffenen [[Kaisertums]] Österreich übernommen, nachdem das [[Heilige]] Römische Reich 1806 aufgelöst wurde"}, {"kategorie": "", "text": "Die Krone wurde nach dem [[Habsburger]] Kaiser [[Rudolf]] II. (1576-1612) benannt, für den sie ursprünglich 1602 als [[Kaiserkrone]] des [[Heiligen]] Römischen Reiches geschaffen wurde. Obwohl Rudolf sie selbst nie als offizielle Krone des [[Heiligen]] Römischen Reiches trug, wurde sie später ein zentrales Symbol für das [[Kaisertum]] Österreich"}, {"kategorie": "", "text": "Denn nach der Auflösung des [[Heiligen]] Römischen Reiches und der Gründung des [[Kaisertums]] Österreich 1806 durch [[Franz]] II., nannte sich dieser fortan [[Franz I. Kaiser von Österreich]], und die Rudolfskrone wurde ab diesem Zeitpunkt zur offiziellen [[Kaiserkrone]] des [[Kaisertums]] Österreich, die bis zum Ende der Monarchie 1918 als Zeichen der Herrschaft der [[Habsburger]] Kaiser diente"}, {"kategorie": "", "text": "Die Rudolfskrone zeichnet sich durch ihre prachtvolle Gestaltung aus. Sie besteht aus Gold und ist mit Edelsteinen und Perlen verziert, was ihre Bedeutung als Symbol kaiserlicher Macht und Pracht unterstreicht. Charakteristisch ist der breite, mit edlen Steinen besetzte Kronreif, der von einem kaiserlichen Kreuz bekrönt wird"}, {"kategorie": "", "text": "Die Rudolfskrone ist heute in der [[Wiener]] Schatzkammer in der [[Hofburg]] ausgestellt und gehört zu den wertvollsten und bekanntesten Stücken der [[Habsburgischen]] Reichsinsignien. Sie ist ein zentraler Teil der österreichischen Geschichte und ein eindrucksvolles Beispiel für die Pracht der habsburgischen Herrschaft."}]'::jsonb, ''),
  ('keenigskrone', 'Keenigskrone', '', '', '', '', 'Königskrone', '[{"kategorie": "hist.", "text": "\"Insigne und Symbol der königlichen Macht und Würde\""}, {"kategorie": "", "text": "Die Königskrone wird traditionell von [[Königen]] und Königinnen bei Krönungszeremonien und wichtigen Staatsanlässen getragen und steht für die Autorität und Souveränität des Herrschers"}, {"kategorie": "", "text": "Königskronen sind meist aus Edelmetallen wie Gold gefertigt und mit wertvollen Edelsteinen und Perlen besetzt, um die Macht und den Reichtum des Herrschers sichtbar zu machen. Die Königskrone ist ein Zeichen für die rechtmäßige und göttliche Herrschaft des Königs oder der Königin und symbolisiert die Souveränität über ein Königreich. Sie unterstreicht die besondere Position des Königs als Oberhaupt des Staates"}, {"kategorie": "", "text": "Die Krone ist oft mit weiteren [[Herrschaftsinsignien]] wie [[Zepter]], [[Reichsapfel]] und [[Reichsschwert]] verbunden, die zusammen die Autorität und Aufgaben des Herrschers repräsentieren"}, {"kategorie": "", "text": "Im [[Heiligen]] Römischen Reich und später im österreichischen [[Kaisertum]] spielten Königskronen ebenfalls eine wichtige Rolle. Zum Beispiel besaßen die Habsburger als Könige von Böhmen und Ungarn separate Kronen für diese Königreiche, die ihre Herrschaft über diese Territorien repräsentierten. Die Stephanskrone in Ungarn und die Wenzelskrone in Böhmen sind berühmte Königskronen, die Teil der habsburgischen Herrschaftsinsignien waren und heute in Prag und Budapest verwahrt werden"}, {"kategorie": "", "text": "Königskronen sind nicht nur Insignien, sondern auch wertvolle Kunstwerke und Kulturgüter, die die Geschichte und Kultur eines Landes widerspiegeln. Sie sind oft in Schatzkammern ausgestellt und gelten als Symbole nationaler Identität und königlicher Tradition"}]'::jsonb, ''),
  ('kaisareich', 'Kaisareich', '', '', '', '', 'Kaiserreich', '[{"kategorie": "hist.", "text": "\"ein Territorium oder eine Staatseinheit, die von einem [[Kaiser]] oder einer Kaiserin regiert wird\""}, {"kategorie": "", "text": "Im Fall von Österreich bezieht sich das Kaiserreich einerseits auf das [[Kaisertum]] Österreich, das im Jahr 1804 von Kaiser [[Franz]] II. gegründet wurde, und andererseits auf die spätere [[Doppelmonarchie]] Österreich-Ungarn (ab 1867)"}, {"kategorie": "", "text": "Das [[Kaisertum]] Österreich wurde von Kaiser Franz II. (als Franz I. von Österreich) ins Leben gerufen, als eine Reaktion auf die Bedrohung durch das expandierende napoleonische Frankreich. Franz II. war der letzte Kaiser des [[Heiligen]] Römischen Reiches, das er 1806 aufgrund der politischen Entwicklungen und der Kriege mit [[Napoleon]] auflöste"}, {"kategorie": "", "text": "Mit der Gründung des Kaisertums Österreich schuf er einen neuen kaiserlichen Titel, um das Prestige und die zentrale Stellung der Habsburger in Europa zu sichern"}, {"kategorie": "", "text": "Das Kaiserreich Österreich war ein Vielvölkerstaat und umfasste neben deutschsprachigen Gebieten auch Ungarn, Böhmen, Mähren, Galizien, Teile Italiens, Kroatien und Slowenien. Die ethnische und kulturelle Vielfalt führte zu Spannungen, aber auch zu einem breiten kulturellen und wirtschaftlichen Austausch"}, {"kategorie": "", "text": "Die Verwaltung war stark zentralisiert, und die [[Habsburger]] regierten als absolute Monarchen. Das Kaiserreich stand unter dem starken Einfluss der katholischen Kirche und des Adels"}, {"kategorie": "", "text": "In der ersten Hälfte des 19. Jahrhunderts war das Kaiserreich Österreich unter dem Staatskanzler Klemens Wenzel von [[Metternich]] führend in der Restauration nach den [[Napoleonischen]] Kriegen. Metternich formte die europäische Ordnung beim [[Wiener]] Kongress (1814–1815) und etablierte Österreich als führende konservative Macht, die liberale und nationale Bewegungen in Europa bekämpfte"}, {"kategorie": "", "text": "Nach den Revolutionsjahren 1848 und der militärischen Niederlage im [[Deutschen]] Krieg 1866 kam es 1867 zum [[Ausgleich]] mit Ungarn, wodurch das Kaiserreich Österreich zur [[Doppelmonarchie]] Österreich-Ungarn wurde. Kaiser [[Franz]] Joseph I. regierte von nun an als Kaiser von Österreich und König von Ungarn in Personalunion. Die Doppelmonarchie bestand aus zwei fast autonomen Teilen: dem „Königreich Ungarn“ und dem „Kaiserreich Österreich“. Diese wurden durch gemeinsame Ministerien für Außenpolitik, Finanzen und Militär miteinander verbunden"}, {"kategorie": "", "text": "Das Kaiserreich Österreich-Ungarn zerbrach am Ende des [[Ersten]] Weltkriegs (1914–1918). Nach der Niederlage und dem Zusammenbruch des Vielvölkerstaates dank nationalistischer Bestrebungen in vielen Regionen dankte Kaiser Karl I. 1918 ab, und Österreich wurde zur Republik."}]'::jsonb, ''),
  ('keenig', 'Keenig', '', '', '', '', 'König', '[{"kategorie": "hist.", "text": "\"Monarch, der ein Königreich regiert und gewöhnlich durch eine Dynastie, also eine familiäre [[Erbfolge]], seine Herrschaft weitergibt\""}, {"kategorie": "", "text": "In Bezug auf Österreich und die [[Habsburger-Dynastie]] hatten die Herrscher Österreichs zwar keinen spezifischen Titel „König von Österreich“, waren jedoch Könige über zahlreiche Gebiete innerhalb und außerhalb des [[Heiligen]] Römischen Reiches, insbesondere über Böhmen und Ungarn. Die königlichen Titel der Habsburger spielten eine wichtige Rolle in der Machtausweitung und territorialen Festigung Österreichs"}, {"kategorie": "", "text": "Die Habsburger trugen seit dem Mittelalter diverse Königstitel, darunter vor allem die Titel des Königs von Böhmen und des Königs von Ungarn. Diese Königreiche waren zentrale Bestandteile der habsburgischen Herrschaft, insbesondere nach dem Erwerb Ungarns durch die [[Schlacht]] bei Mohács 1526"}, {"kategorie": "", "text": "Diese Titel verstärkten die Macht und das Ansehen der Habsburger und ermöglichten die Bildung eines Vielvölkerreiches unter der Kontrolle eines Monarchen"}, {"kategorie": "", "text": "Im Heiligen Römischen Reich wurde der [[römisch-deutsche]] König gewählt und später in Rom zum [[Kaiser]] gekrönt. [[Die]] Habsburger stellten ab dem 15. Jahrhundert fast ununterbrochen den römisch-deutschen König und späteren Kaiser, was ihnen bedeutende Macht und Einfluss sicherte. Der Titel des römisch-deutschen Königs war für die Habsburger ein wichtiger Teil der Legitimation ihrer Herrschaft über die deutschen und benachbarten Gebiete"}, {"kategorie": "", "text": "Böhmen und Ungarn waren die bedeutendsten [[Königreiche]] innerhalb des [[Habsburgerreiches]] und galten als autonome Königreiche, die jedoch unter der Kontrolle der Habsburger standen. Die böhmische und ungarische Königswürde verliehen den Habsburgern das Recht, über diese Gebiete zu regieren, was die Grundlage für das [[Kaisertum]] Österreich und später die [[Doppelmonarchie]] Österreich-Ungarn legte"}, {"kategorie": "", "text": "Mit dem [[Österreichisch-Ungarischen]] Ausgleich von 1867 entstand die [[Doppelmonarchie]] Österreich-Ungarn, in der der Habsburger Monarch als [[Kaiser]] von Österreich und gleichzeitig als [[König]] von Ungarn in Personalunion regierte. Dieser Ausgleich betonte die Bedeutung des ungarischen Königstitels und der Eigenständigkeit Ungarns innerhalb der Doppelmonarchie, die bis zum Ende der Monarchie 1918 bestehen blieb."}]'::jsonb, ''),
  ('keenigreich', 'Keenigreich', '', '', '', '', 'Königreich', '[{"kategorie": "hist.", "text": "\"politische Einheit oder ein Staat, der von einem [[König]] oder einer Königin regiert wird\""}, {"kategorie": "", "text": "Ein Königreich ist üblicherweise eine monarchische Staatsform, in der die Herrschaft durch Geburt oder dynastische Erbfolge weitergegeben wird. Der [[König]] oder die Königin ist das Staatsoberhaupt und symbolisiert die Einheit und Souveränität des Landes. Die Macht des Monarchen kann absolut sein ([[absolute]] Monarchie) oder durch eine Verfassung und Parlamente eingeschränkt ([[konstitutionelle]] Monarchie)"}, {"kategorie": "", "text": "Ein Königreich umfasst festgelegte geographische Grenzen und eine definierte Bevölkerung, die dem König untersteht. Das Territorium kann aus mehreren Regionen, Städten und Provinzen bestehen, die zentral oder dezentral verwaltet werden"}, {"kategorie": "", "text": "Die [[Habsburger]], die über das [[Heilige]] Römische Reich und später das [[Kaisertum]] Österreich regierten, führten mehrere Königreiche in ihrer Herrschaft: Böhmen, Ungarn, Galizien und Lodomerien sowie Teile Italiens wie das Königreich Lombardo-Venetien. Diese Königreiche blieben in vielen Angelegenheiten eigenständig, aber durch die Dynastie der Habsburger miteinander verbunden. Sie bildeten das Fundament für das habsburgische Vielvölkerreich und später für die [[Doppelmonarchie]] Österreich-Ungarn"}, {"kategorie": "", "text": "In der [[Doppelmonarchie]] Österreich-Ungarn (1867–1918) bestanden das [[Kaiserreich]] Österreich und das [[Königreich]] Ungarn nebeneinander als autonome Teile unter einem [[Monarchen]]"}, {"kategorie": "", "text": "Ein Königreich hat eine starke symbolische Bedeutung, da es die kulturelle und historische Identität eines Landes repräsentiert. Die [[Krone]], das [[Zepter]] und andere [[Insignien]] sind Zeichen der königlichen Macht und werden häufig in Zeremonien genutzt, um die Autorität des Königs und die Kontinuität der Monarchie darzustellen."}]'::jsonb, ''),
  ('eabfoige', 'Eabfoige', '', '', '', '', 'Erbfolge', '[{"kategorie": "hist.", "text": "\"die gesetzlich oder traditionell geregelte Reihenfolge, in der Titel, Ländereien und Herrschaftsrechte innerhalb einer Dynastie weitergegeben werden\""}, {"kategorie": "", "text": "In Bezug auf die [[Habsburger-Dynastie]] war die Erbfolge entscheidend für die Stabilität und den territorialen Zusammenhalt des habsburgischen Vielvölkerreiches. Die Habsburger nutzten eine komplexe Erbfolgeregelung, um ihre Herrschaft in Mitteleuropa zu sichern und zu erweitern"}, {"kategorie": "", "text": "Die [[Habsburger]] setzten auf das Prinzip der Primogenitur, bei dem das älteste männliche Familienmitglied das Erbe und die Herrschaft übernimmt. Dies sollte Konflikte vermeiden und die territoriale Einheit des Herrschaftsgebiets sichern. Es gab jedoch auch Phasen der Herrschaftsteilung zwischen verschiedenen Familienlinien, insbesondere zwischen den spanischen und österreichischen Habsburgern, die jeweils ihre eigenen Territorien und Titel vererbten"}, {"kategorie": "", "text": "Die [[Pragmatische]] Sanktion wurde 1713 von Kaiser [[Karl]] VI. erlassen und war eine bedeutende Erbfolgeregelung für das [[Habsburgerreich]]. Sie ermöglichte die weibliche Thronfolge und erklärte, dass die Habsburgischen [[Erblande]] unteilbar und untrennbar seien. Da Karl VI. keinen männlichen Nachfolger hatte, sicherte die Pragmatische Sanktion seiner Tochter [[Maria]] Theresia die Thronfolge und damit den Fortbestand der habsburgischen Herrschaft"}, {"kategorie": "", "text": "Die Frage der Erbfolge führte zu mehreren großen Konflikten, wie dem [[Österreichischen]] Erbfolgekrieg (1740–1748), der nach dem Tod Karls VI. ausbrach, als europäische Mächte die Thronfolge Maria Theresias infrage stellten. Auch die Aufteilung der spanischen Erblande nach dem Tod des kinderlosen Königs [[Karl]] II. von Spanien 1700 führte zum [[Spanischen]] Erbfolgekrieg (1701–1714) und einer dauerhaften Teilung der Habsburger-Dynastie in eine österreichische und eine spanische Linie"}, {"kategorie": "", "text": "Nach der Gründung des [[Kaisertums]] Österreich 1804 und später der [[Doppelmonarchie]] Österreich-Ungarn 1867 blieb die Erbfolge in der Habsburgerfamilie eine festgelegte Praxis, die auf männliche Nachkommen fokussiert war, nach dem Prinzip der Primogenitur"}, {"kategorie": "", "text": "Nach dem Ende des [[Ersten]] Weltkriegs und der Abdankung Kaiser [[Karl]] I. im Jahr 1918 wurde das [[Kaiserreich]] Österreich aufgelöst, und die Habsburger verloren ihre [[Erblande]]. Die [[Erste]] Republik Österreich verbot 1919 der Habsburgerfamilie die Rückkehr, solange sie jedwede Ansprüche auf die Monarchie nicht aufgebe"}, {"kategorie": "", "text": "Die [[Habsburgergesetze]] regeln bis heute den Umgang mit den ehemaligen habsburgischen Besitzungen und der Titelverwendung in Österreich."}]'::jsonb, ''),
  ('heazog', 'Heazog', '', '', '', '', 'Herzog', '[{"kategorie": "hist.", "text": "\"hoher [[Adelstitel]] in Österreich und im [[Heiligen]] Römischen Reich des Mittelalters und der Frühen Neuzeit, der ursprünglich einem Herrscher über ein [[Herzogtum]] verliehen wurde\""}, {"kategorie": "", "text": "Der Titel leitet sich vom althochdeutschen „herizogo“ ab, was „Heerführer“ bedeutet, und bezeichnete ursprünglich einen militärischen Anführer, der später auch zivile Verwaltungsaufgaben übernahm"}, {"kategorie": "", "text": "In Österreich war der Titel des Herzogs besonders bedeutsam, da die [[Markgrafschaft]] Ostarrîchi (Österreich) im Jahr 1156 durch das Privilegium Minus zum Herzogtum erhoben wurde. Dieses Privileg verschaffte Österreich eine weitreichende Autonomie innerhalb des [[Heiligen]] Römischen Reiches. Die Herzöge von Österreich, zunächst die Babenberger und später die Habsburger, hatten damit umfangreiche Herrschaftsrechte und waren vergleichsweise unabhängige Herrscher"}, {"kategorie": "", "text": "Der Titel „Herzog von Österreich“ behielt seine Bedeutung, bis die [[Habsburger]] im 14. Jahrhundert durch das [[Privilegium]] Maius den Titel des [[Erzherzogs]] einführten, der ihren Anspruch auf eine noch höhere Stellung symbolisieren sollte. Ab diesem Zeitpunkt verlor der Herzogstitel in Österreich an Bedeutung, blieb aber als historischer Titel bestehen und ist bis heute eng mit der frühen Geschichte der österreichischen Herrscherhäuser verbunden."}]'::jsonb, ''),
  ('eazheazog', 'Eazheazog', '', '', '', '', 'Erzherzog', '[{"kategorie": "hist.", "text": "\"spezieller Titel, der besonders für Österreich von großer Bedeutung war\""}, {"kategorie": "", "text": "Der Titel \"Erzherzog\" wurde durch [[Rudolf]] IV. von Habsburg im Jahr 1358/59 mit dem [[Privilegium]] Maius geschaffen, um den Rang des österreichischen [[Herzogs]] zu erhöhen und die [[Habsburger]] als den anderen [[Fürsten]] überlegen darzustellen. Dieser Titel wurde erst 1453 von Kaiser [[Friedrich]] III. offiziell anerkannt"}, {"kategorie": "", "text": "Die Habsburger waren die ersten und einzigen Träger dieses Titels im [[Heiligen]] Römischen Reich. Der Titel wurde zunächst verwendet, um die Herrscher über die [[Kernlande]] der Habsburger, Niederösterreich und Oberösterreich, zu bezeichnen"}, {"kategorie": "", "text": "Der Titel \"Erzherzog\" war nicht nur eine Aufwertung des Status innerhalb der Hierarchie des Heiligen Römischen Reiches, sondern sollte auch die Vormachtstellung der Habsburger unter den deutschen Fürsten verdeutlichen. Er gab den Habsburgern eine symbolische Überlegenheit, die sie im Kampf um die [[Kaiserkrone]] des Heiligen Römischen Reiches stärkten"}, {"kategorie": "", "text": "Das Erzherzogtum Österreich umfasste im Wesentlichen die Gebiete des heutigen Niederösterreich, Oberösterreich und Wien. Diese Territorien waren das [[Kernland]] der habsburgischen Macht, die sich später auf andere Teile Europas ausdehnte."}]'::jsonb, ''),
  ('keenigsheisa', 'Keenigsheisa', '', '', '', '', 'Königshäuser', '[{"kategorie": "hist.", "text": "\"herrschende Dynastien und Adelsfamilien, die das Land regierten oder mit ihm eng verbunden waren\""}, {"kategorie": "", "text": "Österreich selbst war lange ein [[Kaisertum]] (1804–1918), weshalb die Herrscherdynastie vor allem als das [[Haus]] Habsburg oder Haus Habsburg-Lothringen bekannt ist, und weniger als Königshaus bezeichnet wurde. Die Habsburger stellten über Jahrhunderte die [[Kaiser]] des [[Heiligen]] Römischen Reiches und prägten die mitteleuropäische Geschichte stark"}, {"kategorie": "", "text": "Trotz des Status als Kaisertum gab es Verbindungen zu anderen Königshäusern, etwa durch politische Allianzen und Heiraten mit den Herrscherfamilien Spaniens, Ungarns, Böhmens und weiterer europäischer Königreiche. Das Haus Habsburg hielt zudem den Königstitel in verschiedenen Ländern (z. B. als Könige von Ungarn und Böhmen), wodurch Österreich und sein Herrscherhaus im internationalen Gefüge der Königshäuser eine wichtige Rolle spielten"}, {"kategorie": "", "text": "Zusammengefasst bezeichnet „Königshäuser“ in Bezug auf Österreich also vor allem die mächtigen Adelsdynastien, allen voran die [[Habsburger]], die durch politische, kulturelle und familiäre Verflechtungen eng mit anderen europäischen Königreichen verbunden waren."}]'::jsonb, ''),
  ('reichskrone', 'Reichskrone', '', '', '', '', 'Reichskrone', '[{"kategorie": "hist.", "text": "\"Krone, die vom 11. Jahrhundert bis zum Ende des [[Heiligen]] Römischen Reiches 1806 als Krönungsinsigne für die römisch-deutschen Kaiser verwendet wurd\""}, {"kategorie": "", "text": "Diese Krone, oft auch [[Kaiserkrone des Heiligen Römischen Reiches]] genannt, symbolisierte die höchste Macht und Herrschaftsautorität der Kaiser über das Heilige Römische Reich"}, {"kategorie": "", "text": "Die Kaiserkrone ist einzigartig in ihrer Gestaltung und unterscheidet sich von anderen europäischen Kronen. Sie besteht aus acht goldenen Platten, die mit Edelsteinen und Emailarbeiten verziert sind und eine oktogonale Form bilden. Auf der Vorderseite der Krone befindet sich ein großer Kreuzaufsatz, der die Verbindung zwischen [[Kaiser]] und Kirche sowie die göttliche Legitimation des [[Kaisertums]] symbolisiert. Die Verzierungen zeigen biblische Szenen und Symbole, die die Rolle des Kaisers als Verteidiger des Glaubens unterstreichen"}, {"kategorie": "", "text": "Diese Krone wurde in der Reichskrone-Sammlung der Reichsinsignien aufbewahrt, die heute größtenteils in der [[Schatzkammer]] der [[Wiener]] Hofburg ausgestellt sind"}, {"kategorie": "", "text": "Die Kaiserkrone ist ein bedeutendes Kunstwerk und Symbol für die lange Geschichte und das kulturelle Erbe des Heiligen Römischen Reiches."}]'::jsonb, 'Kaisakrone des Heiligen Römischen Reiches'),
  ('keanlaunde', 'Keanlaunde', '', '', '', '', 'Kernlande', '[{"kategorie": "hist.", "text": "\"die zentralen, ursprünglichen Gebiete, die den Kern des habsburgischen Herrschaftsgebiets bildeten\""}, {"kategorie": "", "text": "Dazu gehören insbesondere die heutigen Bundesländer Niederösterreich, Oberösterreich und die Steiermark"}, {"kategorie": "", "text": "Diese Regionen waren die politischen und wirtschaftlichen Zentren der [[Habsburger-Monarchie]] und bildeten das Fundament, von dem aus die [[Habsburger]] im Laufe der Jahrhunderte ihre Macht im [[Heiligen]] Römischen Reich und darüber hinaus ausdehnten"}, {"kategorie": "", "text": "Im weiteren Sinne kann „Kernlande“ auch auf andere Gebiete der Habsburgermonarchie ausgeweitet werden, die für die Herrschaft zentral waren, etwa Tirol oder Kärnten"}, {"kategorie": "", "text": "Der Begriff unterstreicht die Bedeutung dieser Regionen als Ausgangspunkt und stabilen Machtbereich der [[Habsburger-Dynastie]] im deutschsprachigen Raum und Mitteleuropa."}]'::jsonb, ''),
  ('ungabruckn', 'Ungabruckn', '', '', '', '', 'Ungerbrücke', '[{"kategorie": "allg.", "text": "(Stadtpark/Ungargasse)"}]'::jsonb, ''),
  ('schdiigabruckn', 'Schdiigabruckn', '', '', '', '', 'Stiegerbrücke', '[{"kategorie": "allg.", "text": "(Stiegergasse/Längenfeldgasse)"}]'::jsonb, ''),
  ('schdodtparkbruckn', 'Schdodtparkbruckn', '', '', '', '', 'Stadtparkbrücke', '[{"kategorie": "allg.", "text": "(Stadtpark/Am Heumarkt)"}]'::jsonb, ''),
  ('marxabruckn', 'Marxabruckn', '', '', '', '', 'Marxerbrücke', '[{"kategorie": "allg.", "text": "(Stubenring/Marxergasse)"}]'::jsonb, ''),
  ('magdalenanbruckn', 'Magdalenanbruckn', '', '', '', '', 'Magdalenenbrücke', '[{"kategorie": "allg.", "text": "(Steggasse/Linke Wienzeile)"}]'::jsonb, ''),
  ('lobkowitzbruckn', 'Lobkowitzbruckn', '', '', '', '', 'Lobkowitzbrücke', '[{"kategorie": "allg.", "text": "(Linke Wienzeile/Schönbrunner Straße)"}]'::jsonb, ''),
  ('braeuhausbruckn', 'Bräuhausbruckn', '', '', '', '', 'Bräuhausbrücke', '[{"kategorie": "allg.", "text": "(Bergmillergasse/Stampfergasse)"}]'::jsonb, ''),
  ('auhofbruckn', 'Auhofbruckn', '', '', '', '', 'Auhofbrücke', '[{"kategorie": "allg.", "text": "(Wientalstraße/Linzer Straße)"}]'::jsonb, ''),
  ('guidnbruckn', 'Guidnbruckn', '', '', '', '', 'Guldenbrücke', '[{"kategorie": "allg.", "text": "Guldenbrücke (Hietzinger Kai/Guldengasse)"}]'::jsonb, ''),
  ('baumgatnbruckn', 'Baumgatnbruckn', '', '', '', '', 'Baumgartenbrücke', '[{"kategorie": "allg.", "text": "(Hietzinger Kai/Hadikgasse)"}]'::jsonb, ''),
  ('nevillbruckn', 'Nevillbruckn', '', '', '', '', 'Nevillebrücke', '[{"kategorie": "allg.", "text": "Nevillebrücke (Nevillegasse/Brückengasse)"}]'::jsonb, ''),
  ('schoenbrunnabruckn', 'Schönbrunnabruckn', '', '', '', '', 'Schönbrunnerbrücke', '[{"kategorie": "allg.", "text": "(Grünbergstraße/Winckelmannstraße)"}]'::jsonb, ''),
  ('schdubnbruckn', 'Schdubnbruckn', '', '', '', '', 'Stubenbrücke', '[{"kategorie": "allg.", "text": "(Wollzeile/Landstraßer Hauptstraße)"}]'::jsonb, ''),
  ('pilgrambruckn', 'Pilgrambruckn', '', '', '', '', 'Pilgrambrücke', '[{"kategorie": "allg.", "text": "(Pilgramgasse/Hofmühlgasse)"}]'::jsonb, ''),
  ('magareedngiatlbruckn', 'Magareedngiatlbruckn', '', '', '', '', 'Margaretengürtelbrücke', '[{"kategorie": "allg.", "text": "(Margaretengürtel/Gumpendorfer Gürtel)"}]'::jsonb, ''),
  ('scheemalbruckn', 'Scheemalbruckn', '', '', '', '', 'Schemerlbrücke', '[{"kategorie": "allg.", "text": "\"nördlichste Wiener [[Donaukanalbrücke]], welche den 19. und 20. Wiener Gemeindebezirk ([[Döbling]] und [[Brigittenau]]) miteinander verbindet\""}, {"kategorie": "", "text": "Sie befindet sich unmittelbar an der Abzweigung des [[Donaukanals]] vom Hauptstrom der [[Donau]] beim [[Brigittenauer]] Sporn"}, {"kategorie": "", "text": "Die Schemerlbrücke wurde zwischen 1894 und 1899 nach einem Entwurf von Otto Wagner erbaut und dient als wesentlicher Bestandteil der [[Nussdorfer]] Wehr- und Schleusenanlage"}, {"kategorie": "", "text": "Sie ist nach Joseph Maria Schemerl von Leythenbach, einem bedeutenden österreichischen Architekten und Wasserbauingenieur, benannt, der für seine Arbeiten im Bereich der Donau-Regulierung bekannt war"}, {"kategorie": "", "text": "Die markanten Bronzelöwen, die heute als Logo der Wiener Autofabrik Gräf & Stift genutzt werden, wurden vom Bildhauer Rudolf Weyr geschaffen"}, {"kategorie": "", "text": "Die Brücke, als Fachwerkbrücke konstruiert, spielt eine wichtige Rolle bei der Regulierung des Wasserflusses aus der [[Donau]] in den [[Donaukanal]], da sie die Wehrfelder umfasst, die bei Bedarf ins Wasser abgesenkt werden können. Diese Funktion macht die Schemerlbrücke zu einem zentralen Element im Wiener Hochwasserschutz"}, {"kategorie": "", "text": "Neben der Brücke steht eine Schleusenanlage für die Schifffahrt zur Verfügung. Konstruktiv ist die Brücke aufgrund ihrer doppelten Fachwerkstruktur besonders stabil und spielt eine Schlüsselrolle sowohl bei der Wasserregulierung"}, {"kategorie": "", "text": "Die Schemerlbrücke dient heute vor allem auch als Radfahrer- und Fußgängerbrücke, die den Zugang zur Nussdorfer Wehr- und Schleusenanlage ermöglicht."}]'::jsonb, ''),
  ('brigittaschbitz', 'Brigittaschbitz', '', '', '', '', 'Brigittaspitz', '[{"kategorie": "", "text": "Er befindet sich im 20. Wiener Gemeindebezirk ([[Brigittenau]]) und wurde am 23. Januar 1973 durch den Gemeinderatsausschuss für Kultur offiziell benannt"}, {"kategorie": "", "text": "Der Sporn ist baulich einerseits durch die [[Schemerlbrücke]] mit [[Nussdorf]] im 19. Bezirk ([[Döbling]]) verbunden, die über das [[Nussdorfer]] Wehr führt, und andererseits durch die [[Nussdorfer]] Schleusenbrücke mit dem nördlichsten Abschnitt des [[Handelskai]]"}, {"kategorie": "", "text": "Die geographische und wasserbauliche Bedeutung des Brigittenauer Sporns liegt in seiner Funktion als Teilungs- und Regulierungsbauwerk, das den Wasserfluss zwischen der Donau und dem Donaukanal steuert."}]'::jsonb, ''),
  ('schdadionbruckn', 'Schdadionbruckn', '', '', '', '', 'Stadionbrücke', '[{"kategorie": "allg.", "text": "\"Donaukanalbrücke, welche die Bezirke [[Landstraße]] (3. Bezirk) und [[Leopoldstadt]] (2. Bezirk) verbindet\""}, {"kategorie": "", "text": "Ursprünglich als \"Kaiser-Joseph-Brücke\" 1873 errichtet, wurde sie 1920 nach dem nahegelegenen Schlachthof Schlachthausbrücke genannt"}, {"kategorie": "", "text": "1936/37 erfolgte der Neubau im Rahmen eines Arbeitsprogramms der damaligen Regierung, um Zugangsmöglichkeiten zum [[Praterstadion]] (heute [[Ernst-Happel-Stadion]]) zu verbessern"}, {"kategorie": "", "text": "Im [[Zweiten]] Weltkrieg wurde die Brücke 1945 zerstört, jedoch später wieder aufgebaut und 1959-1961 endgültig erneuert"}, {"kategorie": "", "text": "Die heutige Brücke ist eine Stahlbrücke mit einer Spannweite von etwa 55 Metern über den [[Donaukanal]] und hat eine wichtige Verkehrsfunktion als Zubringer zur A4 ([[Ostautobahn]]) und zur A23 ([[Südosttangente]])."}]'::jsonb, ''),
  ('seitnhoofnbruckn', 'Seitnhoofnbruckn', '', '', '', '', 'Seitenhafenbrücke', '[{"kategorie": "allg.", "text": "\"eine im Jahr 2011 eröffnete Straßenbrücke, die den [[Donaukanal]] überquert und den 2. Bezirk ([[Leopoldstadt]]) mit dem 11. Bezirk ([[Simmering]]) verbindet\""}, {"kategorie": "", "text": "Die Brücke wurde im Zuge des Neubaus der [[Freudenauer]] Hafenstraße errichtet und stellt eine neue Verkehrsverbindung dar, um die [[Freudenauer]] Hafenbrücke zu entlasten"}, {"kategorie": "", "text": "Die Seitenhafenbrücke ist etwa 130 Meter lang und 15 Meter breit. Ihre schlanke Konstruktion aus Stahl bietet Platz für Fahrzeuge, Fußgänger und Radfahrer"}, {"kategorie": "", "text": "Die Brücke spielt eine wichtige Rolle für den Individualverkehr und den Betrieb des [[Wiener]] Hafens und verbindet die [[Seitenhafenstraße]] im 2. Bezirk mit der 11. [[Haidequerstraße]] im 11. Bezirk"}, {"kategorie": "", "text": "An ihrem Standort befand sich vorher keine Brücke, und sie trägt ihren Namen nach dem früheren Seitenhafen, der in den 1980er Jahren zugeschüttet wurde, um Platz für Hafenanlagen zu schaffen."}]'::jsonb, ''),
  ('seitnhoofnschdrossn', 'Seitnhoofnschdrossn', '', '', '', '', 'Seitenhafenstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die einst zu einem inzwischen nicht mehr existierenden Seitenhafen des [[Winterhafens]] führte\""}, {"kategorie": "", "text": "Dieser Hafen lag zwischen dem [[Donaukanal]] und dem Hauptarm des Winterhafens. Die Straße beginnt an der Hafenzufahrtsstraße, die eine Verlängerung des [[Handelskais]] ist, und verlief früher als Sackgasse bis zum Donaukanal"}, {"kategorie": "", "text": "Mit dem Bau der [[Seitenhafenbrücke]] im Jahr 2011 wurde die Seitenhafenstraße verlängert und bietet nun eine direkte Verkehrsverbindung vom 2. in den 11. Bezirk ([[Simmering]])"}, {"kategorie": "", "text": "Diese Brücke ermöglicht nicht nur dem motorisierten Verkehr, sondern auch Fußgängern und Radfahrern, den Donaukanal zu überqueren"}, {"kategorie": "", "text": "Die Straße und die Brücke spielen eine wichtige Rolle für die logistische Anbindung des [[Hafens]] Freudenau und der umliegenden Industrie- und Entsorgungsbetriebe in Simmering."}]'::jsonb, ''),
  ('zinnagossn', 'Zinnagossn', '', '', '', '', 'Zinnergasse', '[{"kategorie": "allg.", "text": "\"multifunktionale Gasse im 11. Wiener Gemeindebezirk ([[Simmering]]) im Stadtteil [[Kaiserebersdorf]], die sowohl Wohn- als auch gewerblichen Charakter hat\""}, {"kategorie": "", "text": "Sie wurde am 7. Juli 1894 nach Matthias Zinner, einem Hofjäger der Herrschaft Kaiserebersdorf im 19. Jahrhundert, benannt. Zinner verstarb 1836. Die Zinnergasse trug zuvor den Namen Fabriksgasse"}, {"kategorie": "", "text": "Im Laufe ihrer Geschichte erfuhr die Straße verschiedene Veränderungen: 1927 wurde sie verlängert, und 1957 wurde ein Teil der Zinnergasse in die Fuchsbodengasse integriert, während sie gleichzeitig durch Einbeziehung der 4. Landwehrstraße erneut verlängert wurde"}, {"kategorie": "", "text": "Die Zinnergasse liegt im historischen Stadtteil [[Kaiserebersdorf]] und ist ein Beispiel für die vielen Straßennamen, die nach Persönlichkeiten aus der Umgebung benannt wurden."}]'::jsonb, ''),
  ('schraegsaeubruckn', 'Schrägsäubruckn', '', '', '', '', 'Schrägseilbrücke', '[{"kategorie": "allg.", "text": "\"Autobahnbrücke über den [[Donaukanal]], welche den 2. und 11. Wiener Gemeindebezirk ([[Leopoldstadt]] und [[Simmering]]) miteinander verbindet\""}, {"kategorie": "", "text": "Sie ist Teil der [[A]]4 Ostautobahn und führt den stadteinwärts fahrenden Verkehr zum [[Knoten]] Prater"}, {"kategorie": "", "text": "Eine Schrägseilbrücke ist eine Brückenform, bei der die Fahrbahn durch schräge Seile, die direkt an hohen Pylonen befestigt sind, getragen wird. Diese Bauweise kombiniert Merkmale einer Hängebrücke und einer Balkenbrücke, wobei die Pylone das Gewicht der Fahrbahn über die gespannten Seile abtragen und an die Fundamente weiterleiten. Die Schrägseile sind meist in einem oder zwei schräg nach oben verlaufenden Seilpaaren an den Pylonen befestigt"}, {"kategorie": "", "text": "Die Schrägseilbrücke über den Donaukanal in Wien ist ein typisches Beispiel dieser Konstruktion. Sie wurde zwischen 1973 und 1975 erbaut und hat eine Gesamtlänge von 229 Metern"}, {"kategorie": "", "text": "Die Schrägseilbrücke zeichnet sich durch ihre Effizienz im Lastenmanagement aus und ermöglicht große Spannweiten ohne die Notwendigkeit vieler Stützpfeiler"}, {"kategorie": "", "text": "Die Schrägseilbrücke in Wien ist nicht nur ein funktionales Bauwerk für den Verkehr, sondern auch ein interessantes Beispiel für moderne Brückenbaukunst, die sowohl technische als auch ästhetische Anforderungen erfüllt."}]'::jsonb, ''),
  ('wintahoofnbruckn', 'Wintahoofnbruckn', '', '', '', '', 'Winterhafenbrücke', '[{"kategorie": "allg.", "text": "\"bedeutende Eisenbahnbrücke, die den [[Donaukanal]] und den [[Hafen]] Freudenau (auch als [[Winterhafen]] bezeichnet) überquert sowie den 2. mit dem 11. Wiener Gemeindebezirk ([[Leopoldstadt]] und [[Simmering]]) miteinander verbindet\""}, {"kategorie": "", "text": "Konkret verbindet sie die [[Donauuferbahn]] entlang des rechten Donauufers mit der [[Donauländebahn]], die als West-Ost-Verbindung den Süden des Wiener Stadtgebiets durchquert"}, {"kategorie": "", "text": "Diese Brücke ist von großer Bedeutung für den Güterverkehr und stellt eine zentrale Verbindung zwischen den Bahnstrecken in Wien dar"}, {"kategorie": "", "text": "Die ursprüngliche Winterhafenbrücke wurde 1880 erbaut, um eine Verbindung zwischen der Donauuferbahn und der Donauländebahn herzustellen. Diese Eisenbahnstrecken dienten dem Güterverkehr, insbesondere zur Versorgung von Industriebetrieben und dem Warenumschlag an der Donau. Die Brücke wurde von der kkStB (Kaiserlich-königliche österreichische Staatsbahnen) betrieben und war Teil des erweiterten Stadtbahnnetzes, das sowohl für den Personen- als auch den Güterverkehr genutzt wurde"}, {"kategorie": "", "text": "Im Zweiten Weltkrieg wurde der [[Hafen]] Freudenau zu einem strategisch wichtigen Ziel für Bombenangriffe. Obwohl die Brücke zunächst unbeschädigt blieb, wurde sie am Ende des Krieges im April 1945 von der Wehrmacht gesprengt. Danach blieben die Pfeiler und Zufahrtsrampen der Brücke als Ruinen bestehen, ohne dass ein Wiederaufbau unmittelbar erfolgte"}, {"kategorie": "", "text": "Dieser wurde erst Jahrzehnte später umgesetzt. Nach längerer Verzögerung wurde 2007 mit dem Bau der neuen Brücke begonnen, und im Sommer 2008 konnte der Bau vorzeitig abgeschlossen werden"}, {"kategorie": "", "text": "Die neue Brücke hat eine Länge von 168 Metern und besteht aus einer Fachwerkbrücke über den Donaukanal sowie einer Trogbrücke über den Winterhafen. Der Wiederaufbau wurde durch den zunehmenden Güterverkehr und den Ausbau des Wiener Hafens beschleunigt. Seit Ende 2008 ist die Winterhafenbrücke wieder in Betrieb"}, {"kategorie": "", "text": "Die Winterhafenbrücke spielt eine wichtige Rolle im Güterverkehr Wiens, insbesondere im Zusammenhang mit dem [[Wiener]] Hafen Freudenau. Der Hafenumschlag, insbesondere im Containerverkehr, ist ein zentraler Bestandteil der Wirtschaftsaktivitäten in diesem Bereich. Im Jahr 2007 wurden dort über 320.000 Container umgeschlagen, was einer Kapazität von 70 Güterzügen pro Woche entspricht. Die Brücke ermöglicht eine reibungslose Verbindung zwischen den wichtigen Güterverkehrsstrecken und trägt somit zur Effizienz des städtischen und regionalen Schienenverkehrs bei."}]'::jsonb, ''),
  ('donauufabaun', 'Donauufabaun', '', '', '', '', 'Donauuferbahn', '[{"kategorie": "allg.", "text": "\"Eisenbahnstrecke in Wien, die entlang des rechten Ufers der [[Donau]] verläuft\""}, {"kategorie": "", "text": "Sie wurde zwischen 1876 und 1880 erbaut und verbindet die [[Franz-Josefs-Bahn]] im Norden mit der [[Donauländebahn]] im Süden. Die Donauuferbahn begleitet die [[Donau]] auf der gesamten Länge der heutigen  [[Donauinsel]], die durch die [[Donauregulierung]] entstanden ist, und verläuft durch die Wiener Bezirke 2. ([[Leopoldstadt]]), 11. ([[Simmering]]), 19. ([[Döbling]]) und 20. ([[Brigittenau]])"}, {"kategorie": "", "text": "Ursprünglich war sie eine eingleisige Bahnstrecke mit einer Länge von 12,8 Kilometern und diente vor allem dem Güterverkehr, insbesondere zur Unterstützung der Donauschifffahrt und der umliegenden Industrieanlagen"}, {"kategorie": "", "text": "Die Donauuferbahn wurde als Teil des Wiener Stadtbahnnetzes konzipiert und 1876 eröffnet, um den Güterumschlag zwischen der Donau und den neu entstandenen Industriebetrieben sowie Lagerhäusern zu bewältigen. Sie diente dazu, Güter von der Donau in die Stadt und zu anderen Bahnstrecken weiterzuleiten. Der Personenverkehr auf der Strecke war nie von großer Bedeutung und wurde 1939 eingestellt"}, {"kategorie": "", "text": "Während des [[Zweiten]] Weltkriegs wurden Teile der Strecke zerstört, darunter die [[Winterhafenbrücke]], die eine wichtige Verbindung zur [[Donauländebahn]] darstellte. Diese Brücke wurde erst in den 2000er Jahren im Zuge der Modernisierung des [[Hafens]] Freudenau wieder neu errichtet"}, {"kategorie": "", "text": "Heute wird die Donauuferbahn auch von der [[S-Bahn-Linie]] S45 genutzt, die den nördlichen Teil der Strecke im dichten Intervall bedient. Es gibt auch Überlegungen, die S45 entlang der Donauuferbahn weiter nach Süden zu verlängern, um einen zukünftigen S-Bahn-Ring um Wien zu schaffen."}]'::jsonb, ''),
  ('kaisazug', 'Kaisazug', '', '', '', '', 'Kaiserzug', '[{"kategorie": "allg.", "text": "\"luxuriöser Eisenbahnzug der [[Habsburger]] Monarchie, der von den Monarchen [[Franz]] Joseph I. und später [[Karl]] I. für Reisen im In- und Ausland genutzt wurde (auch als \"kaiserlicher Hofzug\" oder \"k.u.k. Hofsalonzug\" bezeichnet)\""}, {"kategorie": "", "text": "Der Zug wurde 1891 im Auftrag der österreichischen Bahnverwaltungen durch die k.k. Generaldirektion der österreichischen Eisenbahnen in Auftrag gegeben und von der Waggonfabrik Ringhoffer in Prag gebaut"}, {"kategorie": "", "text": "Dieser Hofzug diente offiziellen Reisen des Kaisers und enthielt luxuriös ausgestattete Salonwagen, Schlaf- und Speisewagen sowie Abteile für die kaiserliche Familie und deren Gefolge"}, {"kategorie": "", "text": "Der Zug von 1891 war der erste einheitliche Hofzug, der speziell für den Kaiser und seinen Hofstaat gebaut wurde. Er bestand aus acht Wagen mit luxuriösen Interieurs, darunter ein Salonwagen für den Kaiser, ein Speisewagen und ein Küchenwagen. Die Innenausstattung war prunkvoll, im Makart-Stil gehalten, mit Samtvorhängen, edlen Hölzern und goldenen Verzierungen"}, {"kategorie": "", "text": "Mit dem Ende der Habsburgermonarchie 1918 und dem Abdanken von Kaiser Karl I. wurde der Hofsalonzug aufgelöst. Einige der Waggons wurden von den Nachfolgestaaten übernommen, andere wurden verkauft oder in Museen ausgestellt"}, {"kategorie": "", "text": "Der außen sehr schlichte, 1873 gebaute Hofsalonwagen Hz 011 von Kaiserin Elisabeth ist im Wiener [[Technischen]] Museum ausgestellt. Über eine seitliche Galerie kann man durch die Fenster in das prunkvolle Innere des Wagens blicken."}]'::jsonb, ''),
  ('salonzug', 'Salonzug', '', '', '', '', 'Salonzug', '[{"kategorie": "allg.", "text": "\"luxuriöser Eisenbahnzug der [[Habsburger]] Monarchie, der von den Monarchen [[Franz]] Joseph I. und später [[Karl]] I. für Reisen im In- und Ausland genutzt wurde (auch als \"Kaiserzug\" bzw. \"kaiserlicher Hofzug\" oder \"k.u.k. Hofsalonzug\" bezeichnet)\""}, {"kategorie": "", "text": "Der Zug wurde 1891 im Auftrag der österreichischen Bahnverwaltungen durch die k.k. Generaldirektion der österreichischen Eisenbahnen in Auftrag gegeben und von der Waggonfabrik Ringhoffer in Prag gebaut"}, {"kategorie": "", "text": "Dieser Hofzug diente offiziellen Reisen des Kaisers und enthielt luxuriös ausgestattete Salonwagen, Schlaf- und Speisewagen sowie Abteile für die kaiserliche Familie und deren Gefolge"}, {"kategorie": "", "text": "Der Zug von 1891 war der erste einheitliche Hofzug, der speziell für den Kaiser und seinen Hofstaat gebaut wurde. Er bestand aus acht Wagen mit luxuriösen Interieurs, darunter ein Salonwagen für den Kaiser, ein Speisewagen und ein Küchenwagen. Die Innenausstattung war prunkvoll, im Makart-Stil gehalten, mit Samtvorhängen, edlen Hölzern und goldenen Verzierungen"}, {"kategorie": "", "text": "Mit dem Ende der Habsburgermonarchie 1918 und dem Abdanken von Kaiser Karl I. wurde der Hofsalonzug aufgelöst. Einige der Waggons wurden von den Nachfolgestaaten übernommen, andere wurden verkauft oder in Museen ausgestellt"}, {"kategorie": "", "text": "Der außen sehr schlichte, 1873 gebaute Hofsalonwagen Hz 011 von Kaiserin Elisabeth ist im Wiener [[Technischen]] Museum ausgestellt. Über eine seitliche Galerie kann man durch die Fenster in das prunkvolle Innere des Wagens blicken."}]'::jsonb, ''),
  ('augossn', 'Augossn', '', '', '', '', 'Augasse', '[{"kategorie": "allg.", "text": "\"Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die 1862 nach den früheren Augebieten der [[Donau]] benannt wurde, die sich in diesem Bereich erstreckten\""}, {"kategorie": "", "text": "Die Augasse verläuft oberhalb des ehemaligen Donauuferhangs und markiert die westliche Grenze des Stadtteils [[Althangrund]]"}, {"kategorie": "", "text": "Ursprünglich erstreckte sich hier eine Stromlandschaft mit Auen, also typischen Uferlandschaften von Flüssen oder Bächen, die durch den Wechsel zwischen niedrigen und hohen Wasserständen geprägt wurden"}, {"kategorie": "", "text": "Heute grenzt die Augasse an den Standort des ehemaligen Frachtenbahnhofs der [[Franz-Josefs-Bahn]]"}, {"kategorie": "", "text": "Die Augasse ist heute eine Wohnstraße in einem verkehrsberuhigten Wohngebiet."}]'::jsonb, ''),
  ('noadbeagbruckn', 'Noadbeagbruckn', '', '', '', '', 'Nordbergbrücke', '[{"kategorie": "allg.", "text": "\"Straßenbrücke im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die über die [[Franz-Josefs-Bahn]] verläuft\""}, {"kategorie": "", "text": "Sie verbindet die beiden Seiten des Stadtteils [[Althangrund]] und dient als wichtige Verkehrsachse in diesem Bereich"}, {"kategorie": "", "text": "Die Brücke ist nach Karl Gustav Noé, Edler von Nordberg benannt, einem bedeutenden österreichischen Beamten und früheren Polizeidirektor von Wien"}, {"kategorie": "", "text": "Sie spielt eine bedeutende Rolle für den Straßenverkehr und verbindet wichtige Straßen wie die [[Nordbergstraße]] und den [[Josef-Holaubek-Platz]]"}, {"kategorie": "", "text": "Die Brücke trägt dazu bei, die beiden Teile des stark urbanisierten Gebiets auf beiden Seiten der [[Franz-Josefs-Bahn]] miteinander zu verbinden, und ermöglicht einen schnellen Übergang zwischen den angrenzenden Stadtteilen"}, {"kategorie": "", "text": "Durch ihre Lage in der Nähe wichtiger Einrichtungen wie dem [[Universitätszentrum]] Althangrund, dem ehemaligen Frachtenbahnhof der Franz-Josefs-Bahn und dem heutigen [[Bundesamtsgebäude]] Josef-Holaubek-Platz ist sie besonders für den Alltagsverkehr von Bedeutung"}, {"kategorie": "", "text": "Die Nordbergbrücke ist Teil des dichten Verkehrsnetzes, das das Gebiet durchzieht, und verbindet unter anderem auch den Verkehr mit der nahegelegenen [[Müllverbrennungsanlage]] Spittelau und anderen bedeutenden Punkten im 9. Bezirk"}]'::jsonb, ''),
  ('noadbeagschdrossn', 'Noadbeagschdrossn', '', '', '', '', 'Nordbergstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 9. Wiener Gemeindebezirk ([[Alsergrund]]), welche die beiden Seiten des Stadtteils [[Althangrund]] verbindet und als wichtige Verkehrsachse in diesem Bereich dient\""}, {"kategorie": "", "text": "Die Straße ist nach Karl Gustav Noé, Edler von Nordberg benannt, einem bedeutenden österreichischen Beamten und früheren Polizeidirektor von Wien"}, {"kategorie": "", "text": "Das Gebiet entlang der Nordbergstraße bzw. rund um den [[Franz-Josefs-Bahnhof]] und dessen Überbauungen, die unter anderem das [[Bundesamtsgebäude]] Josef-Holaubek-Platz, das [[Universitätszentrum]] Althangrund, das Objekt Nordbergstraße 15, die Post, ein Parkhaus und die Unicredit Bank Austria AG umfassen, ist in der Stadt relativ isoliert und weist nur wenig Interaktion mit dem umliegenden Stadtgebiet auf. Um diese Isolation zu überwinden, arbeitet die Stadt Wien in Zusammenarbeit mit privaten Partnerunternehmen an der Revitalisierung des Areals"}, {"kategorie": "", "text": "In den 2010er-Jahren wurden mehrere Pläne zur Neugestaltung des Gebiets entwickelt. Der Umbau des Objekts Nordbergstraße 15 wurde bis Ende 2018 abgeschlossen, und in den kommenden Jahren soll das gesamte Areal im Rahmen des Projekts \"Althan Quartier\" neu gestaltet werden. Ein Siegerprojekt für die Neugestaltung wurde im April 2018 ausgewählt."}]'::jsonb, ''),
  ('vabindungsbogn', 'Vabindungsbogn', '', '', '', '', 'Verbindungsbogen', '[{"kategorie": "allg.", "text": "\"ehemalige Eisenbahnstrecke in den Wiener Bezirken [[Döbling]] (19. Bezirk) und [[Alsergrund]] (9. Bezirk), die von 1901 bis 1991 in Betrieb war (auch \"Verbindungskurve\" bzw. \"alte Nordbergbrücke\" genannt)\""}, {"kategorie": "", "text": "Sie verband die Gürtellinie (heute U6) bei der Station [[Nußdorfer]] Straße mit der B10845Donaukanallinie (heute U4) bei der Station Brigittabrücke (heute [[Friedensbrücke]])"}, {"kategorie": "", "text": "Der Verbindungsbogen war 1,415 Kilometer lang und wurde ursprünglich als Teil der [[Wiener]] Dampfstadtbahn errichtet. Er bestand aus 55 steinernen Viaduktbögen und sechs stählernen Brücken und war die einzige Stadtbahnstrecke, die vollständig in Hochlage verlief"}, {"kategorie": "", "text": "Die Strecke diente dazu, eine direkte Verbindung zwischen den beiden Stadtbahnlinien zu ermöglichen. 1991 wurde der Betrieb auf dem Verbindungsbogen eingestellt, um Platz für den Bau der Verkehrsstation Wien Spittelau zu schaffen. Ein 300 Meter langes Teilstück des Verbindungsbogens blieb jedoch erhalten und wird bis heute von der U6 befahren"}, {"kategorie": "", "text": "Der stillgelegte Rest der Strecke wurde unter dem Namen [[Bertha-Zuckerkandl-Weg]] als Fuß- und Radweg umgewidmet. Ein einzelner Bogen der Strecke wurde abgerissen, während der Großteil der alten Viaduktbögen noch besteht."}]'::jsonb, ''),
  ('kunstgeweabeschui', 'Kunstgeweabeschui', '', '', '', '', 'Kunstgewerbeschule', '[{"kategorie": "", "text": "Die Kunstgewerbeschule wurde am 27. September 1867 auf Initiative von Kaiser [[Franz]] Joseph I. gegründet und eröffnete am 1. Oktober 1868 als „Oberste Schule für das Kunstgewerbe“. Ihr ursprünglicher Standort war im Palais Brenner in Wien, bevor sie 1872 in das neu errichtete Gebäude des Österreichischen Museums für Kunst und Industrie (heute [[MAK]] – Museum für angewandte Kunst) am Stubenring übersiedelte"}, {"kategorie": "", "text": "Die Kunstgewerbeschule hatte das Ziel, Künstler und Handwerker in den angewandten Künsten auszubilden und die künstlerische Gestaltung von Gebrauchsgegenständen zu fördern. Sie war stark mit der britischen Arts and Crafts-Bewegung verwandt und setzte auf handwerkliche Qualität sowie künstlerische Innovation"}, {"kategorie": "", "text": "Die Schule spielte eine zentrale Rolle in der Entwicklung des [[Wiener]] Jugendstils und des modernen Designs und war eng mit der [[Wiener]] Secession und der [[Wiener]] Werkstätte verbunden. Bekannte Künstler wie Koloman Moser, Josef Hoffmann und Gustav Klimt lehrten oder studierten hier"}, {"kategorie": "", "text": "Im Jahr 1999 ging aus der Kunstgewerbeschule die Universität für angewandte Kunst Wien hervor. Das [[MAK]], das Österreichische Museum für angewandte Kunst, besteht weiterhin unabhängig und setzt sich mit der Geschichte und den Werken der angewandten Kunst auseinander."}]'::jsonb, ''),
  ('frochtnbaunhof', 'Frochtnbaunhof', '', '', '', '', 'Frachtenbahnhof', '[{"kategorie": "allg.", "text": "\"ehemals bedeutende logistische Drehscheibe und ein zentrales Element der Infrastruktur im 10. Wiener Gemeindebezirk ([[Favoriten]]), das lange Zeit eine besondere Stellung in der Stadt innehatte\""}, {"kategorie": "", "text": "Der Frachtenbahnhof befand sich auf einem weitläufigen Areal, das nach dem [[Zweiten]] Weltkrieg bis zu seinem Abbruch als „No-go-Zone“ galt, da es durch eine hohe Mauer vom restlichen Stadtgebiet abgeschottet war"}, {"kategorie": "", "text": "Diese Mauer, die ursprünglich dazu gedacht war, das Bahngelände vor unbefugtem Betreten zu schützen, prägte die Umgebung stark. Viele Anwohner und insbesondere Kinder und Jugendliche entwickelten im Laufe der Zeit eine Faszination für diesen abgeschiedenen und teilweise gefährlichen Ort"}, {"kategorie": "", "text": "Für die Kinder der umliegenden Viertel war der Frachtenbahnhof ein Abenteuerspielplatz, trotz seiner Gefahren. Sie schlichen sich durch Lücken in der Mauer, erkundeten die Lagerhallen und sammelten die Kohlen, die von den Güterzügen gefallen waren"}, {"kategorie": "", "text": "Für die Erwachsenen war der Frachtenbahnhof ebenfalls ein Ort, der trotz seiner offiziellen Nutzung oft auf halblegalen Wegen durchquert wurde, um Zeit zu sparen. So nutzten sie geheime Pfade, die von den Portieren mit einem Augenzwinkern geduldet wurden, um schneller in benachbarte Viertel wie den Schweizergarten oder zum Südbahnhof zu gelangen"}, {"kategorie": "", "text": "Der Frachtenbahnhof war auch ein Ort, der von illegalen Aktivitäten durchzogen war. Mit der Zeit verfielen Teile des Geländes, und das Postgebäude etwa wurde nach seiner Stilllegung von Gruppen genutzt, die das Bauwerk als Quelle für Rohstoffe, insbesondere Kupfer, plünderten. Diese kriminellen Aktivitäten waren schwer zu kontrollieren, da das Gelände so weitläufig und unübersichtlich war"}, {"kategorie": "", "text": "Darüber hinaus war der Frachtenbahnhof ein sozialer Treffpunkt für viele Anwohner, insbesondere dank des legendären Gasthauses „Zum Kamptaler“, das mitten in dieser sonst unzugänglichen und industriellen Gegend eine schattige Oase bot. Viele Treffen und Besprechungen endeten dort, und das Lokal war über die Jahrzehnte ein fester Bestandteil des Lebens rund um den Frachtenbahnhof"}, {"kategorie": "", "text": "Obwohl der Frachtenbahnhof schließlich abgerissen wurde, um Platz für das moderne [[Sonnwendviertel]], das [[Quartier]] Belvedere und den neuen [[Wiener]] Hauptbahnhof zu machen, blieb die Erinnerung an dasLokal  „Kamptaler“ erhalten, das heute unter neuem Namen weitergeführt wird."}]'::jsonb, ''),
  ('vabindungsbaun', 'Vabindungsbaun', '', '', '', '', 'Verbindungsbahn', '[{"kategorie": "allg.", "text": "\"Bezeichnung für mehrere Bahnstrecken in Wien, die in unterschiedlichen Zeitperioden errichtet wurden, um die Hauptbahnhöfe und Güterbahnhöfe der Stadt miteinander zu verbinden\""}, {"kategorie": "", "text": "Sie dienten sowohl dem Personen- als auch dem Güterverkehr und waren von großer strategischer Bedeutung, insbesondere auch für das Militär und die Industrie"}, {"kategorie": "", "text": "Erste Verbindungsbahn (1851 vollendet): Diese Strecke führte vom [[Nordbahnhof]] beim [[Praterstern]] über den [[Donaukanal]] zum [[Südbahnhof]] (heute [[Hauptbahnhof]]). Heute ist sie ein stark frequentierter Teil der Wiener [[S-Bahn-Stammstrecke]], die [[Floridsdorf]] über den [[Praterstern]] mit [[Meidling]] verbindet"}, {"kategorie": "", "text": "Zweite Verbindungsbahn: Diese Strecke verbindet den [[Westbahnhof]] über [[Penzing]], [[Speising]] und [[Hetzendorf]] mit der [[Südbahn]] und der [[Donauländebahn]]"}, {"kategorie": "", "text": "Dritte Verbindungsbahn ([[Donauländebahn]]): Diese Güterbahnstrecke führt von [[Meidling]] über [[Hetzendorf]] an das rechte Ufer der regulierten Donau, wo sie in die [[Donauuferbahn]] mündet. Sie verbindet diverse Strecken der [[Südbahn]], [[Ostbahn]] und [[Pottendorfer]] Linie"}, {"kategorie": "", "text": "Floridsdorfer Hochbahn (Italienerschleife): Diese während des [[Ersten]] Weltkriegs errichtete Verbindung zwischen Nordwestbahn und Nordbahn war von strategischer Bedeutung und wurde nach Jahrzehnten des Stillstands wieder in Betrieb genommen"}, {"kategorie": "", "text": "Vorortelinie: Diese verbindet die [[Westbahn]] mit der [[Franz-Josefs-Bahn]] und bietet seit 1987 wieder Personenverkehr als [[S-Bahn-Linie]] S45"}, {"kategorie": "", "text": "Die verschiedenen Verbindungsbahnen hatten ursprünglich auch strategische Bedeutung für das k.u.k. Militär und spielten im Güterverkehr eine große Rolle, da sie Umschlagplätze und Industriegleise miteinander verbanden."}]'::jsonb, ''),
  ('oebb', 'ÖBB', '', '', '', '', 'ÖBB', '[{"kategorie": "", "text": "Seitdem besteht die ÖBB-Holding AG als Muttergesellschaft, die drei operative Tochtergesellschaften umfasst: den Personenverkehr, den Güterverkehr (Rail Cargo Austria) und die Infrastruktur"}, {"kategorie": "", "text": "Neben diesen Kernbereichen betreiben die ÖBB auch zahlreiche Tochtergesellschaften, etwa im Bereich Busverkehr und Touristik. Die Holding befindet sich vollständig im Eigentum der [[Republik]] Österreich"}, {"kategorie": "", "text": "Die ÖBB gehen auf die Verstaatlichung der Eisenbahnen in der Zeit der [[Donaumonarchie]] zurück. Seit dem Zerfall [[Österreich-Ungarns]] 1918 und der Gründung der [[Republik]] Österreich im Jahr 1919 firmieren sie als Staatsbahnen"}, {"kategorie": "", "text": "1969 wurden die ÖBB als eigenständiger Wirtschaftskörper mit eigener Verwaltung geschaffen, und 1992 erfolgte die Umwandlung in eine Kapitalgesellschaft. Mit der Bahnreform 2004 entstand der ÖBB-Konzern, wie er heute besteht, um den Anforderungen der EU und einer effizienteren Verwaltung zu entsprechen"}, {"kategorie": "", "text": "Die ÖBB betreiben ein Netz von 4.965 Kilometern, von denen etwa 3.650 Kilometer elektrifiziert sind. Der Güterverkehr umfasst jährlich mehr als 94 Millionen Tonnen. Jährlich werden über 200 Millionen Passagiere im Personenverkehr befördert"}, {"kategorie": "", "text": "Die ÖBB sind auch für bedeutende Infrastrukturprojekte wie den Brenner-Basistunnel und den Semmering-Basistunnel verantwortlich, die den Schienenverkehr in Österreich und Europa stark verbessern sollen."}]'::jsonb, ''),
  ('ostbaun', 'Ostbaun', '', '', '', '', 'Ostbahn', '[{"kategorie": "allg.", "text": "\"historische Bahnstrecke, die ursprünglich als Wien-Raaber Eisenbahn gebaut wurde, später verstaatlicht und als k.k. Staatsbahn betrieben wurde\""}, {"kategorie": "", "text": "Sie umfasst drei Hauptstrecken von Wien aus: nach Budapest südlich der Donau, nach Pressburg und Budapest nördlich der Donau, sowie Richtung Brünn über Laa an der Thaya"}, {"kategorie": "", "text": "Die Ostbahn war eine bedeutende Verkehrsverbindung zwischen Wien und den südöstlichen Regionen der damaligen [[Habsburgermonarchie]]. Sie wurde bis 1883 stetig ausgebaut, unter anderem zur Durchgangsstrecke des Orient-Express auf seiner Route von Paris nach Konstantinopel bzw. Bukarest"}, {"kategorie": "", "text": "Im Jahr 1909 wurden die Strecken der privaten StEG verstaatlicht und von der k.k. Staatsbahn übernommen. So wurde die Ostbahn zu einem bedeutenden Teil des k.u.k. Eisenbahnnetzes"}, {"kategorie": "", "text": "Die Bedeutung der Ostbahn veränderte sich nach dem Zerfall der Habsburgermonarchie und erneut nach dem Zweiten Weltkrieg. Die Bedeutung der Strecke nach Ungarn nahm nach 1945 stark ab, vor allem durch den Eisernen Vorhang. Seit dem Fall des Eisernen Vorhangs und im Zuge des EU-Projekts der Transeuropäischen Netze (TEN) wird die Ostbahn jedoch wieder aufgewertet, insbesondere die Verbindung über Bruck an der Leitha nach Budapest"}, {"kategorie": "", "text": "Ein Teil der Ostbahn wird heute als [[S-Bahn-Linie]] S60 zwischen Wien Hauptbahnhof und Bruck an der Leitha betrieben. Geplante Ausbauprojekte wie die Elektrifizierung und der zweigleisige Ausbau der Strecke nach Marchegg sollen die Bedeutung der Ostbahn weiter steigern, insbesondere die Verbindung nach Pressburg. Die Strecke durch das Marchfeld ist dabei mit rund 30 Kilometern die längste gerade Gleistrasse in Österreich."}]'::jsonb, ''),
  ('donaulaendebaun', 'Donauländebaun', '', '', '', '', 'Donauländebahn', '[{"kategorie": "allg.", "text": "\"wichtige Bahnstrecke in Wien, die den Südwesten, den Süden und den Südosten der Stadt durchquert\""}, {"kategorie": "", "text": "Sie verbindet mehrere radiale Bahnlinien und dient primär dem Schienengüterverkehr, wobei sie als Umgehungsbahn eine zentrale Rolle im Wiener Bahnnetz spielt"}, {"kategorie": "", "text": "Die Strecke beginnt bei Ober-Hetzendorf an der [[Verbindungsbahn]] und verläuft von dort in Richtung Osten bis zur [[Winterhafenbrücke]], über die sie in die [[Donauuferbahn]] übergeht. Die Donauländebahn ist nach der [[Donaulände]] benannt und hat eine Länge von 20,5 Kilometern"}, {"kategorie": "", "text": "Die Donauländebahn wurde am 3. Mai 1872 eröffnet, um den Transport von Erzen vom Erzberg zu den Hochöfen der Innerberger Hauptgewerkschaft in Klein Schwechat zu ermöglichen. Sie war außerdem entscheidend für den Anschluss von mehreren Industriebetrieben, wie beispielsweise der Brauerei Dreher"}, {"kategorie": "", "text": "Heute ist die Donauländebahn ein wichtiger Bestandteil des Güterverkehrsnetzes in Wien und verbindet verschiedene Bahnstrecken wie die [[Pottendorfer]] Linie, die [[Ostbahn]], die [[Pressburger]] Bahn sowie den [[Zentralverschiebebahnhof]] Wien-Kledering. Am östlichen Ende schließt sie an die [[Donauuferbahn]] an und ermöglicht somit eine vollständige Umfahrung des rechtsufrigen Stadtgebiets von Wien"}, {"kategorie": "", "text": "Die Donauländebahn ist für den österreichischen Schienengüterverkehr von großer Bedeutung, da sie als Umgehungsbahn eine zentrale Rolle in der Anbindung verschiedener Industriebetriebe und Hafenanlagen spielt. Sie verbindet den [[Zentralverschiebebahnhof]] Wien-Kledering mit den Bahnstrecken im Süden und Südosten der Stadt und ermöglicht so eine effiziente Güterverteilung in und um Wien. Zudem trägt die Strecke zur Verbindung des Wiener Schienennetzes mit wichtigen Häfen, insbesondere dem [[Hafen]] Freudenau und dem [[Hafen]] Albern, bei."}]'::jsonb, ''),
  ('donaulaendn', 'Donauländn', '', '', '', '', 'Donauländen', '[{"kategorie": "allg.", "text": "\"eine seit etwa 1890 gebräuchliche Bezeichnung für die Uferstraßen entlang des Hauptstroms der Donau und des Donaukanals in Wien\""}, {"kategorie": "", "text": "Diese Uferstraßen entstanden im Zuge der [[Donauregulierung]] und umfassen wichtige Verkehrswege wie den [[Handelskai]] und die [[Donauuferbahn]]"}, {"kategorie": "", "text": "Am [[Donaukanal]] tragen verschiedene Straßen entlang des Ufers den Namen \"Lände\", wie die [[Nußdorfer]] Lände, die [[Heiligenstädter]] Lände, die [[Spittelauer]] Lände, die [[Brigittenauer]] Lände, die [[Rossauer]] Lände, die [[Weißgerber]] Lände, die [[Erdberger]] Lände und die [[Simmeringer]] Lände"}, {"kategorie": "", "text": "Eine \"Lände\" ist im Schifffahrtskontext eine einfache Anlegestelle an einem Gewässer, die als einfacher Binnenhafen dient, wobei das Ufer befestigt ist, aber ohne aufwendige Hafenstrukturen wie separate Hafenbecken."}]'::jsonb, ''),
  ('wiinawoidtunnoeoe', 'Wiinawoidtunnöö', '', '', '', '', 'Wienerwaldtunnel', '[{"kategorie": "allg.", "text": "\"doppelröhriger, 13 Kilometer langer Eisenbahntunnel, der seit dem 9. Dezember 2012, nach achtjähriger Bauzeit, in Betrieb ist\""}, {"kategorie": "", "text": "Er ist ein Teil des Trans-Europäischen Netzes (Paris, Wien, Budapest, Bratislava)"}, {"kategorie": "", "text": "Die Tunneltrasse unterquert den nördlichen Wienerwald und ist ein Teil der Schnellfahrstrecke Wien-Salzburg (Neue [[Westbahn]])"}, {"kategorie": "", "text": "Das Westportal befindet sich bei Chorherrn im Tullnerfeld, das Ostportal in Wien im Stadtteil [[Hadersdorf-Weidlingau]]"}, {"kategorie": "", "text": "Nach dem Ostportal ist die Neubaustrecke unterirdisch mit der alten Westbahntrasse und dem [[Lainzer]] Tunnel in einer Weichenhalle verbunden. Mit dem Lainzer Tunnel ist die Verbindung zum [[Hauptbahnhof]] hergestellt"}, {"kategorie": "", "text": "Der Wienerwaldtunnel ist für eine Höchstgeschwindigkeit von 250 km/h zugelassen. Als Sicherheitseinrichtungen wurden alle 500 Meter Notausstiege eingebaut. Brandmeldeanlagen, Notruffernsprecher, Hochdrucklöschleitungen und Belüftungsanlagen vervollständigen die Rettungseinrichtungen im Tunnel"}, {"kategorie": "", "text": "Das Gleisbett ist so ausgeführt, dass die ganze Strecke mit Straßenfahrzeugen befahren werden kann. Die schnellsten Züge durchqueren den drittlängsten Bahntunnel Österreichs in knappen fünf Minuten. Die Baukosten betrugen 617 Millionen Euro."}]'::jsonb, ''),
  ('westbaun', 'Westbaun', '', '', '', '', 'Westbahn', '[{"kategorie": "allg.", "text": "\"eine der bedeutendsten Bahnstrecken Österreichs, die Wien und Salzburg miteinander verbindet (auch \"Kaiserin-Elisabeth-Bahn\" genannt)"}, {"kategorie": "", "text": "Die 1856 gegründete Strecke wurde nach Kaiserin Elisabeth ([[Sisi]]), der Frau von [[Kaiser]] Franz Joseph I., benannt und war ein wichtiges Projekt zur Schaffung einer schnellen Verbindung zwischen Wien und den westlichen Teilen des Kaiserreichs"}, {"kategorie": "", "text": "Die gesamte Strecke von Wien nach Salzburg wurde 1860 fertiggestellt. Im Laufe der Zeit wurde die Westbahn kontinuierlich ausgebaut und modernisiert, insbesondere durch den viergleisigen Ausbau und die Elektrifizierung"}, {"kategorie": "", "text": "Die Westbahn spielt heute eine zentrale Rolle im österreichischen Bahnnetz und gehört zu den am stärksten frequentierten Strecken des Landes. Sie ist sowohl für den Personen- als auch für den Güterverkehr von großer Bedeutung und Teil des Trans-Europäischen Verkehrsnetzes (TEN)"}, {"kategorie": "", "text": "Modernisierungen und Hochgeschwindigkeitsabschnitte ermöglichen Fahrten mit bis zu 250 km/h, wodurch die Fahrzeiten zwischen Wien und Salzburg erheblich verkürzt wurden. Neben den [[ÖBB]] bedient auch das private Eisenbahnunternehmen WESTbahn GmbH die Strecke"}, {"kategorie": "", "text": "Die Strecke umfasst zahlreiche Tunnel, darunter den [[Lainzer]] Tunnel und den [[Wienerwaldtunnel]], und führt durch den landschaftlich reizvollen [[Wienerwald]]"}, {"kategorie": "", "text": "Sie hat Anschluss an wichtige Städte und Bahnknotenpunkte wie St. Pölten, Linz, Wels und Salzburg und verbindet damit die wichtigsten urbanen Zentren Österreichs."}]'::jsonb, ''),
  ('westbaunschdrossn', 'Westbaunschdrossn', '', '', '', '', 'Westbahnstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsverbindung, die nach der [[Kaiserin-Elisabeth-Bahn]] (später [[Westbahn]]) benannt wurde\""}, {"kategorie": "", "text": "Die Straße erhielt 1862 ihren Namen und erstreckt sich in Ost-West-Richtung von der [[Neubaugasse]] bis zum [[Urban-Loritz-Platz]] am Neubaugürtel"}, {"kategorie": "", "text": "Vor 1862 hatte die Straße andere Namen, je nach Abschnitt: Sie hieß Lammgasse (nach dem Haus \"Zum grünen Lamm\") und Kirchengasse"}, {"kategorie": "", "text": "Der Bereich, der heute die Westbahnstraße bildet, wurde durch den Abbruch des Linienwalls ab 1894 neu gestaltet"}, {"kategorie": "", "text": "Eine wichtige Neuerung war die Einführung der Straßenbahnlinie 49, die ab dem 10. Jänner 1902 die Westbahnstraße bis zur [[Kaiserstraße]] bediente und später bis zum [[Gürtel]] verlängert wurde"}, {"kategorie": "", "text": "Die Linie 49 verbindet die Westbahnstraße mit der [[Wiener]] Ringstraße und dem westlichen Stadtteil [[Hütteldorf]] - eine Verbindung, die bis heute besteht."}]'::jsonb, ''),
  ('donaukanalbruckn', 'Donaukanalbruckn', '', '', '', '', 'Donaukanalbrücken', '[{"kategorie": "allg.", "text": "\"all jene Brücken, die den Donaukanal in Wien als Straßen-, Bahn- oder Fußgängerbrücken überqueren\""}, {"kategorie": "", "text": "Viele Donaukanalbrücken wurden im Zuge der [[Wiener]] Operation am Ende des [[Zweiten]] Weltkriegs zerstört und ach 1945 vielfach durch moderne Stahlbetonbrücken ersetzt"}, {"kategorie": "", "text": "Der Donaukanal, einst ein wichtiger Verkehrsweg, war schon in der Römerzeit von Brücken überquert. Die älteste nachweisbare Brücke war die Schlagbrücke aus dem Jahr 1439, die später zur Schwedenbrücke wurde. Diese Brücken verbanden die Stadt mit dem nordöstlichen Umland"}, {"kategorie": "", "text": "Die wichtigsten Donaukanalbrücken sind heute: (i) [[Schemerlbrücke]] (1898, überspannt das [[Nussdorfer]] Wehr), (ii) [[Heiligenstädter]] Brücke (1883-1889, bedeutende Straßenbrücke im Norden Wiens), (iii) [[Friedensbrücke]] (1924-1926, ursprünglich als Brigittabrücke bekannt, verbindet den Alsergrund (9. Bezirk) und die Brigittenau (20. Bezirk), (iv) [[Schwedenbrücke]] (1909-1911 - ehemals als Ferdinandsbrücke bezeichnet, gehört zu den ältesten Brücken über den Donaukanal, verbindet die Bezirke Innere Stadt [1. Bezirk] und Leopoldstadt [2. Bezirk]), (v) [[Aspernbrücke]] (1913-1919 verbindet die Bezirke Innere Stadt [1. Bezirk] und Leopoldstadt [2. Bezirk]), (vi) [[Erdberger]] Brücke (1971 - moderne Straßenbrücke, überquert im Zuge der Stadtautobahn Südosttangente beim Knoten Wien Prater den Donaukanal und verbindet die Landstraße [3. Bezirk] mit der Leopoldstadt [2. Bezirk]), (vii) [[Rossauer]] Brücke (1983 errichtet, verbindet den 9. Bezirk [Alsergrund] mit dem 2. Bezirk [Leopoldstadt]);  (viii) [[Augartenbrücke]] (errichtet 1929-1931, verbindet den 9. und den 2. Bezirk [Alsergrund bzw. Leopoldstadt]), (ix) [[Salztorbrücke]] (errichtet 1884-1886, ersetzt den ehemaligen Karlskettensteg und verbindet den 1. und 2. Bezirk [Innere Stadt und Leopoldstadt]);  (x) [[Marienbrücke]] (ursprünglich als Rotenturmbrücke bekannt, von 1905 bis 1906 neu errichtet, verbindet den 1. und 2. Bezirk [Innere Stadt und Leopoldstadt]); (xi) [[Franzensbrücke]] (errichtet 1847-1848 errichtet, gehört zu den ältesten Brücken über den Donaukanal, verbindet die Bezirke 2 und 3 [Leopoldstadt und Landstraße]), (xii) [[Rotundenbrücke]] (erbaut 1871/1872, verbindet die Bezirke 2 und 3 [Leopoldstadt und Landstraße]), (xiii) [[Stadionbrücke]] (errichtet ursprünglich von 1874 bis 1876, umgebaut 1936, verbindet die Bezirke 2 und 3 [Leopoldstadt und Landstraße]), (xiv) [[Seitenhafenbrücke]] (2011 eröffnete Straßenbrücke, verbindet die Seitenhafenstraße am linken Ufer, im 2. Bezirk [Leopoldstadt], mit der Haidequerstraße am rechten Ufer, im 11. Bezirk [Simmering], (xv) [[Freudenauer]] Hafenbrücke (errichtet 1958, überquert den Donaukanal im Bereich des Freudenauer Hafens und verbindet das Hafengebiet im 2. Bezirk [Leopoldstadt] mit dem 11. Bezirk [Simmering]), (xvi) [[Schrägseilbrücke]] (verbindet die Bezirke Simmering und Leopoldstadt, ist Teil der A4 Ostautobahn und führt den stadteinwärts fahrenden Verkehr zum Knoten Prater), (xvii) [[Spittelauer]] Brücke (erbaut 1992, verbindet die Bezirke Döbling [19. Bezirk] und Brigittenau [20.Bezirk]), sowie (xviii) [[Winterhafenbrücke]] (erbaut 2007-2008 - verbindet den Stadtteil Albern [heute Teil des 11. Bezirkes, Simmering], mit dem 2. Bezirk [Leopoldstadt]."}]'::jsonb, ''),
  ('haidequeaschdrossn', 'Haidequeaschdrossn', '', '', '', '', 'Haidequerstraße', '[{"kategorie": "allg.", "text": "\"Die Haidequerstraße befindet sich im 11. Wiener Gemeindebezirk ([[Simmering]]) und verläuft quer über die [[Simmeringer]] Haide, ein ehemaliges Sumpfgebiet\""}, {"kategorie": "", "text": "Ursprünglich gab es mehrere nummerierte Haidequerstraßen (1. bis 11.), wobei der Versuch unternommen wurde, die Straßen nach dem Vorbild von US-amerikanischen Straßen numerisch zu benennen. Diese Praxis hat sich jedoch nicht bewährt, und einige der Straßen wurden später aus dem amtlichen Register wieder gestrichen oder aufgelassen (darunter die 3., 4., 5. und 6. Haidequerstraße)"}, {"kategorie": "", "text": "Heute existieren nur noch einige der ursprünglich geplanten Haidequerstraßen. Sie befindet sich in einem weniger dicht bebauten Bereich und verläufen durch die Simmeringer Haide, eine frühere sumpfige Landschaft, die heute teils urbanisiert ist"}, {"kategorie": "", "text": "Obwohl die Umgebung urbanisiert wurde, gibt es noch Hinweise auf die ländliche Vergangenheit des Gebiets, wie größere Grünflächen und vereinzelte ältere Gebäude"}, {"kategorie": "", "text": "Die Haidequerstraße ist keine typische Wohnstraße, die in dicht besiedelten Wohnvierteln vorkommt, sondern eher eine Verbindung über eine weitläufigere, ehemals ländliche Gegend."}]'::jsonb, ''),
  ('donaubruckn', 'Donaubruckn', '', '', '', '', 'Donaubrücken', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsverbindungen, welche die [[Donau]] und ihre Nebenarme in Wien überqueren und den älteren Teil Wiens am rechten Donauufer mit den jüngeren Bezirken am linken Donauufer miteinander verbinden\""}, {"kategorie": "", "text": "Die Geschichte der Brücken über die Donau reicht bis ins 15. Jahrhundert zurück, als vorerst nur schmalere Arme des Flusses überquert wurden, wie der [[Donaukanal]]"}, {"kategorie": "", "text": "Die erste dauerhafte Brücke über den Hauptstrom wurde 1440 erbaut, um den Handel und den Personenverkehr zu erleichtern. Aufgrund häufiger Überschwemmungen und Veränderungen im Flussverlauf war der Brückenbau eine große Herausforderung, wobei die ersten Brücken hauptsächlich aus Holz gebaut wurden"}, {"kategorie": "", "text": "Überörtliche Bedeutung haben heute nur jene Brücken, die sowohl über die [[Donau]] als auch über die [[Donauinsel]] und die [[Neue]] Donau führen und somit Verbindungen zwischen dem Stadtgebiet südlich (rechtsufrig) und nördlich (linksufrig) der Donau herstellen"}, {"kategorie": "", "text": "Derzeit führen elf Brücken über beide Stromarme. Die wichtigsten Straßenbrücken hiervon sind: (i) die Nordbrücke (erbaut 1962-1964, verbindet den 19. und 20. Bezirk [Döbling und Brigittenau]), (ii) die Floridsdorfer Brücke (erstmals 1876 eröffnet, in den 1970-er Jahren neu erbaut, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf]), (iii) Brigittenauer Brücke (erbaut 1981-1982, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf), (iv) Reichsbrücke (1976 eingestürzt, dann neu erbaut und 1980 wieder eröffnet, verbindet den 2. und 22. Bezirk [Leopoldsdorf und Donaustadt]), sowie (v) Praterbrücke (achtspurige Autobahnbrücke, erbaut 1967-1970, verbindet den 2. und 22. Bezirk [Leopoldstadt und Donaustadt])"}, {"kategorie": "", "text": "Die wichtigsten Fußgänger- und Radfahrerbrücken sind: (i) Jedleseer Brücke (erbaut 1983, über die Neue Donau, verbindet die Floridsdorfer Stadtteile Jedlesee und Schwarzlackenau), (ii) Steinitzsteg (erbaut 1994-1995, früher Nordsteg, über Donau und Neue Donau, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf]), (iii) Georg-Danzer-Steg (erbaut 1991-1996, auch Bahnbrücke über Donau und Neue Donau, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf]), (iv) Ponte Cagrana (erbaut 2000, Pontonbrücke über die Neue Donau im 22. Bezirk [Donaustadt]), (v) Kaisermühlenbrücke (erbaut 1993, Schrägseilbrücke über die Neue Donau  im 22. Bezirk [Donaustadt]), (vi) Steinspornbrücke (erbautz 1974, führt über die Neue Donau und verbindet die obere Lobau mit der Donauinsel), (vii) Walulisobrücke (1997-98 erbaut, Pontonbrücke über die Neue Donau im 22. Wiener Gemeindebezirk [Donaustadt]), (vii) Wehr 1 (erbaut 1976-1978, Wehranlage, überquert als Spannbetonbrücke die Neue Donau zur Donauinsel), (viii) Wehr 2 (erbaut 1988, Wehranlage, überquert als Spannbetonbrücke die Neue Donau zur Donauinsel), sowie (ix) Kraftwerk Freudenau (erbaut 1992-1998, verbindet den Hafen Freudenau mit der Donauinsel)."}]'::jsonb, ''),
  ('siimhiatn', 'Siimhiatn', '', '', '', '', 'Siebenhirten', '[{"kategorie": "allg.", "text": "\"Stadtteil im 23. Wiener Gemeindebezirk ([[Liesing]]), der erstmals um 1140/1150 als „Subinnirtin“ (übersetzt „sieben Hirten“, möglicherweise die ersten Siedler) urkundlich erwähnt wurde\""}, {"kategorie": "", "text": "Der Ort entwickelte sich ursprünglich als Straßendorf mit charakteristischen Dreiseit- und Hakenhöfen entlang des Petersbachs, westlich der heutigen [[Triester]] Straße. Aus dieser frühen Zeilensiedlung entstand das regelmäßige Straßendorf, das Siebenhirten bis heute prägt"}, {"kategorie": "", "text": "Im 18. Jahrhundert entwickelte sich Siebenhirten zum landwirtschaftlichen Hauptproduktionsgebiet der Herrschaft [[Rodaun]], wobei hauptsächlich Getreide angebaut wurde, während der Weinbau nur eine untergeordnete Rolle spielte"}, {"kategorie": "", "text": "In der zweiten Hälfte des 19. Jahrhunderts setzte mit der beginnenden Industrialisierung ein allmählicher wirtschaftlicher Aufschwung ein, und die Einwohnerzahl wuchs bis 1910 erheblich an"}, {"kategorie": "", "text": "Die heutige Katastralgemeinde Siebenhirten nimmt eine Fläche von 251,22 Hektar ein. Durch den Ort fließt in West-Ost-Richtung der [[Petersbach]]. Im Süden von Siebenhirten befindet sich der von Kleingärten umgebene Schellensee"}, {"kategorie": "", "text": "Ein zentraler Bestandteil der Geschichte von Siebenhirten ist die Teufelsmühle, eine Mühle am Petersbach, die 1477 erstmals urkundlich erwähnt wurde. Die Mühle spielte eine wichtige Rolle in der lokalen Wirtschaft und war bis 1904 in Betrieb. Nach der Zerstörung im [[Zweiten]] Weltkrieg wurde die Teufelsmühle umgebaut und dient heute als Gasthaus, was sie weiterhin zu einem markanten Ort in Siebenhirten macht"}, {"kategorie": "", "text": "In den Jahren 1978 bis 1980 wurde im Nordosten Siebenhirtens nach Plänen von Klara Hautmann, Rudolf Hautmann und Friedrich Rollwagen die große Wohnhausanlage [[Wiener]] Flur erbaut. Im Jahr 1951 hatte der Ort bei der Volkszählung 2839 Einwohner. Heute leben rund 8000 Menschen in Siebenhirten."}]'::jsonb, ''),
  ('ketzagossn', 'Ketzagossn', '', '', '', '', 'Ketzergasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 23. Wiener Gemeindebezirk ([[Liesing]]), welche die Stadtteile [[Siebenhirten]] und [[Rodaun]] mit der angrenzenden niederösterreichischen Gemeinde Perchtoldsdorf verbindet\""}, {"kategorie": "", "text": "Die Ketzergasse ist nach Josef Ketzer (1869–1944) benannt, der von 1918 bis 1928 Bürgermeister von [[Siebenhirten]] war. Josef Ketzer setzte sich maßgeblich für die Belange der Gemeinde ein und spielte eine wichtige Rolle in der Entwicklung des Ortes. Die Straße, die heute seinen Namen trägt, erinnert an seine Verdienste für Siebenhirten"}, {"kategorie": "", "text": "Die Ketzergasse trug nicht immer diesen Namen. Während des Nationalsozialismus wurde sie Adolf-Hitler-Straße genannt, was in dieser Zeit keine Seltenheit war, da viele Straßen nach NS-Führern umbenannt wurden"}, {"kategorie": "", "text": "Nach dem Ende des [[Zweiten]] Weltkriegs, am 6. Mai 1947, erhielt die Straße im Zuge der Entnazifizierung ihren neuen Namen und wurde zunächst als (Siebenhirtener) Hauptstraße bezeichnet. Später erfolgte die Umbenennung zu Ketzergasse, um das Erbe des ehemaligen Bürgermeisters Josef Ketzer zu würdigen"}, {"kategorie": "", "text": "Heute ist die Ketzergasse nicht nur eine bedeutende Verkehrsader, sondern auch ein Symbol für den Wandel der Region von einem ländlich geprägten Gebiet zu einem modernen Teil Wiens."}]'::jsonb, ''),
  ('peedaschboch', 'Peedaschboch', '', '', '', '', 'Petersbach', '[{"kategorie": "allg.", "text": "\"kleiner Fluss, der bei Perchtoldsdorf entspringt und in Maria Lanzendorf in die Schwechat mündet\""}, {"kategorie": "", "text": "Obwohl nur etwa 1,5 Kilometer seines Flusslaufs auf dem heutigen Wiener Stadtgebiet verlaufen, war der Petersbach historisch von großer Bedeutung, insbesondere für die Entwicklung der Gemeinde [[Siebenhirten]] im 23. Wiener Gemeindebezirk ([[Liesing]])"}, {"kategorie": "", "text": "Im Bereich von Siebenhirten trieb der Petersbach einst insgesamt drei Mühlen an: Am westlichen Ortsende befand sich die Mühle der Brauerei Schellenhof, die seit 1719 bestand, im Ortszentrum gab es eine weitere Mühle, und am östlichen Ortsende lag die Teufelsmühle, die 1477 erstmals urkundlich erwähnt wurde. Diese Mühlen nutzten die Abflussmenge des Bachs vollständig aus, indem sie ihn in Mühlbäche ableiteten"}, {"kategorie": "", "text": "Die Mühlen waren für die lokale Landwirtschaft und Industrie von großer Bedeutung, wobei die Schellenhofmühle und die Teufelsmühle bis zum [[Zweiten]] Weltkrieg bestanden und dann zerstört wurden. Der Betrieb der dritten Mühle im Ortszentrum wurde bereits Ende des 19. Jahrhunderts eingestellt"}, {"kategorie": "", "text": "Im 19. Jahrhundert wuchs die Bevölkerung von Siebenhirten stark an, und mit dem Ausbau der Siedlungsflächen nahmen auch die Uferschutzmaßnahmen entlang des Petersbachs zu. Aufgrund des zunehmenden Bebauungsdrucks wurde der Flusslauf des Petersbachs im Laufe des 20. Jahrhunderts in Wien stark reguliert. Im Bereich der Kellerberggasse wurde ein etwa 200 Meter langer Abschnitt des Bachs eingewölbt, während die offenen Strecken mit Trapezprofilen befestigt wurden, um Hochwasser zu verhindern und das Gebiet zu schützen"}, {"kategorie": "", "text": "Trotz der starken Regulierung wurde 2012 ein 200 Meter langer Abschnitt des Petersbachs in Wien renaturiert, um dem Bach ein natürlicheres Flussbett zurückzugeben und die ökologische Funktion zu verbessern. Diese Maßnahme zielt darauf ab, den natürlichen Zustand des Flusses soweit wie möglich wiederherzustellen und gleichzeitig das ökologische Gleichgewicht zu fördern."}]'::jsonb, ''),
  ('kaisamueuen', 'Kaisamüün', '', '', '', '', 'Kaisermühlen', '[{"kategorie": "allg.", "text": "Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]]), gelegen im Nordosten Wiens. Der Stadtteil ist bekannt für seine Lage entlang der Donau, seine historische Entwicklung als Arbeitersiedlung und seine moderne Rolle als Teil des [[UNO-City-Komplexes]] und des Wiener [[Donau-City-Viertels]]"}, {"kategorie": "", "text": "Kaisermühlen hat eine interessante und wechselvolle Geschichte, die bis ins 19. Jahrhundert zurückreicht. Ursprünglich war das Gebiet ein Überschwemmungsgebiet der Donau, das durch seine Nähe zur Donau geprägt wurde. Der Name \"Kaisermühlen\" leitet sich von den Mühlen ab, die hier einst im Auftrag des Kaisers errichtet wurden, um die Wasserkraft der Donau zu nutzen"}, {"kategorie": "", "text": "Im Laufe des 19. Jahrhunderts entwickelte sich Kaisermühlen zu einer Arbeiter- und Industriesiedlung. Hier lebten und arbeiteten viele Menschen, die in den Fabriken und Mühlen der Umgebung beschäftigt waren. Die Wohnbedingungen waren oft beengt, und die Infrastruktur war zunächst unterentwickelt"}, {"kategorie": "", "text": "Im 20. Jahrhundert, insbesondere nach dem Zweiten Weltkrieg, begann Kaisermühlen, sich weiter zu entwickeln und zu modernisieren. Die Errichtung der [[Donauinsel]], eines großen Naherholungsgebiets, sowie die fortschreitende Urbanisierung veränderten den Charakter des Stadtteils grundlegend"}, {"kategorie": "", "text": "Kaisermühlen ist heute ein wichtiger Teil der modernen Entwicklung Wiens, insbesondere durch die Nähe zur [[UNO-City]] (dem Sitz mehrerer Organisationen der Vereinten Nationen) und dem Donau-City-Viertel, einem modernen Stadtteil mit Wolkenkratzern, Büros, Wohnhäusern und Bildungseinrichtungen. Diese Entwicklungen haben Kaisermühlen zu einem bedeutenden Standort für internationale Institutionen, Unternehmen und moderne Wohnprojekte gemacht"}, {"kategorie": "", "text": "Trotz der modernen Entwicklung hat der Stadtteil seinen eigenen Charakter bewahrt, was sich in den alten Arbeiterwohnhäusern, traditionellen Gasthäusern und lokalen Geschäften zeigt."}]'::jsonb, ''),
