  ('iwadiiwaen', 'iwadiiwän', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'überdippeln', '[{"kategorie": "wörtlich", "text": "\"überdübeln\" (vom mittelhochdeutschen \"dübelen\"=\"einen Dübel setzen\" bzw. \"etwas mit Kraft in etwas hineindrücken\")"}, {"kategorie": "fig.", "text": "jemanden überrumpeln, ertappen, \"kalt erwischen\""}, {"kategorie": "fig.", "text": "etwas durchschauen, herausbekommen, [[überreißen]], [[überlauern]], [[übernasern]], [[abstoppen]]"}]'::jsonb, 'Den kaunnst ned so leicht iwadiiwän!'),
  ('iwaranaund', 'iwaranaund', '', '', '', '', 'übereinander', '[{"kategorie": "wörtlich", "text": "\"eines über dem anderen\""}, {"kategorie": "nachgestellt", "text": "Voll-, Total-, Komplett-, (z.B. \"du Depp iwaranaund\" = \"du Volldepp\", \"du Vollpfosten\")"}, {"kategorie": "nachgestellt", "text": "\"hoch zwei\", \"zweimal …\"  (z.B. \"du Depp iwaranaund\" = \"du Depp hoch zwei\", \"du zweimal blöder Depp\")"}]'::jsonb, 'In Swingaklub wiad kreiz und quea puudad - vuadaranaund, hintaranaund, neemaranaund, iwaranaund, untaranaund und duacharanaund!'),
