  ('hapsgee', 'hapsgee', '', '', '', 'Grundwortschatz Wienerisch', 'hapsgehen', '[{"kategorie": "wörtlich", "text": "\"hapsgehen\" (vom mittelhochdeutschen \"hap\"=\"schneller Griff\")"}, {"kategorie": "allg.", "text": "kaputt gehen, in die Brüche gehen, (Deutschland): \"hopsgehen\""}, {"kategorie": "", "text": "zu Tode kommen, verunglücken, ums Leben kommen, sterben"}, {"kategorie": "Gaunerjargon", "text": "\"verhaftet werden\", \"auf frischer Tat ertappt werden\""}]'::jsonb, 'Mia is mei Gschbusi hapsgaungan!'),
  ('iwahaps', 'iwahaps', '', '', '', 'Grundwortschatz Wienerisch', 'überhaps', '[{"kategorie": "wörtlich", "text": "\"über das Haupt\" (Variante von \"überhaupt\", abgeleitet vom mittelhochdeutschen \"über houbet\"=\"über das Haupt\", wobei diese Formulierung ursprünglich aus dem Viehhandel stammt und damit ausgedrückt wird, dass für alle Tiere ein Gesamtpreis zu bezahlen ist, anstatt jedes einzelne Tier [\"jedes einzelne Haupt\"] separat zu zählen und zu verrechnen)"}, {"kategorie": "allg.", "text": "über den Daumen gerechnet, \"pi mal Daumen\", überschlagsmäßig, grob geschätzt, [[schätzomativ]]"}, {"kategorie": "fig.", "text": "vorschnell, überstürzt, überhastet, übereilt"}, {"kategorie": "", "text": "flüchtig, oberflächlich, notdürftig, \"im Schnelldurchlauf\""}]'::jsonb, 'Iwahaps heiratn is ka guade Idee!'),
  ('iwaknechln', 'iwaknechln', '', '', '', '', 'überknöcheln', '[{"kategorie": "wörtlich", "text": "\"über den Knöchel kippen\" (Kompositum aus dem Präfix \"über\"=\"über das Maß hinaus\" und \"knöcheln\"=\"das Knöchelgelenk verdrehen\")"}, {"kategorie": "allg.", "text": "mit dem Fuß umknicken, schief auftreten und den Knöchel verdrehen, sich den Knöchel verstauchen, sich den Fuß verrenken"}]'::jsonb, 'Kaum wora fit, hoda wiida iwaknechld!'),
  ('iwalauan', 'iwalauan', '', '', '', '', 'überlauern', '[{"kategorie": "wörtlich", "text": "\"über das Maß hinaus lauern\"  (Kompositum aus dem Präfix \"über\"=\"hinweg über etwas\" und \"lauern\"=\"aus dem Hinterhalt beobachten\")"}, {"kategorie": "fig.", "text": "etwas spitzkriegen, begreifen, kapieren, [[gneißen]], [[schnallen]]"}, {"kategorie": "", "text": "von etwas Wind bekommen, etwas durchschauen, herausbekommen, [[überreißen]], [[übernasern]], [[iwadiiwän]] (=\"überdübeln\"), [[abstoppen]]"}]'::jsonb, 'De Kundn haum iwalauad, dass unsare Restpostn eigentlich ii ausgee!'),
  ('iwareissn', 'iwareissn', '', '', '', '', 'überreißen', '[{"kategorie": "wörtlich, Bortenweberei", "text": "\"einen Faden überdehnen\" (Kompositum aus dem Präfix \"über\"=\"über das Maß hinaus\" und \"reißen\"=\"durchreißen\")"}, {"kategorie": "fig.", "text": "etwas spitzkriegen, begreifen, [[gneißen]], [[schnallen]]"}, {"kategorie": "", "text": "von etwas Wind bekommen, etwas durchschauen, [[überlauern]], [[übernasern]], [[iwadiiwän]] (=\"überdübeln\"), [[abstoppen]]"}]'::jsonb, 'Wia haum iwahaupt ned iwarissn, um wos bei dem Wickl geed!'),
