  ('iwaringln', 'iwaringln', '', '', '', '', 'überringeln', '[{"kategorie": "wörtlich, Bortenweberei", "text": "\"eine Schnur mit einer anderen überspinnen\"  (Kompositum aus dem Präfix \"über\"=\"hinweg über etwas\" und \"ringeln\"=\"eindrehen\")"}, {"kategorie": "fig.", "text": "etwas spitzkriegen, begreifen, erfassen, [[gneißen]]"}, {"kategorie": "", "text": "von etwas Wind bekommen, etwas durchschauen, herausbekommen, [[überlauern]], [[überreißen]], [[iwadiiwän]]"}]'::jsonb, 'Hädas iwaringld, warada ned kumman!'),
